def fixture_render(application, projection, digest, created_at):
    """The Director's renderer, applied directly: the fixture posts exactly what the Director would."""
    from types import SimpleNamespace
    from director_orchestrator.primary_slack_delivery import render_notification
    record = {key: value for key, value in application["task_record"].items() if key != "qualification_evidence"}
    return render_notification({"projection": {**projection, "application": {**application, "task_record": record}},
                                "projection_digest": digest, "created_at": created_at},
                               SimpleNamespace(slack_channel_id=CHANNEL_FIXTURE, slack_owner_user_id=OWNER))


def task_entry(task_id, offset, *, offline=True, text="DIRECTOR audit trial", answer=None, final_offset=30):
    """One task's API record, deliveries and Slack thread, re-keyed from the collector's fixtures."""
    task, deliveries, messages, _ = tf.sample()
    readback = tf.readback_fixture()
    if offline:
        # The offline double settled its one assignment; its result digest is the outcome's.
        readback.update(assignments=[{**readback["assignments"][0], "result_digest": "sha256:" + "a" * 64}],
                        provider_attempts=[], provider_usage=[])
        tf.recount(readback)
    else:
        task["assignment_outcomes"] = [{"run_id": "provider-run-1", "result": answer or "provider answer",
                                        "provider": "claude", "assignment_sequence": 1,
                                        "review_summary": "fixture review"}]
        readback["execution_mode"] = "live"  # a paid run's persisted mode
    # The outcome's digest is its assignment's (and successful attempt's) result digest, as primary_default records it.
    task["assignment_outcomes"][0]["provider_result_digest"] = (
        "a" * 64 if offline else readback["assignments"][0]["result_digest"].removeprefix("sha256:"))
    for sequence, outcome in enumerate(task["assignment_outcomes"], 1):  # a TaskRecord the renderer accepts
        outcome.setdefault("assignment_sequence", sequence)
        outcome.setdefault("review_summary", "fixture review")
        outcome.setdefault("provider", "claude")
    task.update(status="DONE", qualification_evidence=readback)
    task["intake"]["text"] = text
    messages[0]["text"] = f"<@{BOT}> {text}"
    if answer is None:
        messages[-1]["text"] += "\nActual USD cost: not recorded"
    else:
        messages[-1]["text"] = tf.TASK_ID + " — SUCCEEDED\n" + answer
    messages.insert(1, {"ts": "1789210001.100000", "thread_ts": tf.THREAD, "user": BOT,
                        "text": f"*{tf.TASK_ID} — REQUEST RECEIVED*"})
    blob = json.dumps({"task": task, "deliveries": deliveries, "messages": messages})
    # The gateway's canonical source_event_id for this thread's owner post (slack_bot._forward).
    source = sc_models.canonical_slack_source_event_id({"channel": CHANNEL_FIXTURE, "ts": ts(offset)})
    pairs = ((tf.SOURCE_EVENT, source), (tf.TASK_ID, task_id), (tf.THREAD, ts(offset)), ("1789210001.100000", ts(offset + 1)),
             (tf.FINAL_TS, ts(offset + final_offset)), ('"CFIXTURE"', f'"{CHANNEL_FIXTURE}"'))
    for index, (old, _) in enumerate(pairs):
        blob = blob.replace(old, f"@@{index}@@")
    for index, (_, new) in enumerate(pairs):
        blob = blob.replace(f"@@{index}@@", new)
    entry = json.loads(blob)
    # The collector fixture's clock starts at 10:00:00; this thread's owner post is ts(offset). Every readback and
    # delivery time is re-based onto that post, as the Director records them after the post it handles.
    shift = timedelta(seconds=1789210000 + offset + 1 - 1789207200)  # the task follows its post by a second

    def rebase(value):
        if isinstance(value, dict):
            return {key: rebase(item) for key, item in value.items()}
        if isinstance(value, list):
            return [rebase(item) for item in value]
        if isinstance(value, str) and re.fullmatch(r"2026-09-12T\d\d:\d\d:\d\d(\.\d+)?\+00:00", value):
            return (datetime.fromisoformat(value) + shift).isoformat()
        return value

    entry["task"], entry["deliveries"] = rebase(entry["task"]), rebase(entry["deliveries"])
    # Re-keyed onto this task, each status receipt keeps its producer's id derivation.
    for receipt in entry["task"]["qualification_evidence"]["status_receipts"]:
        receipt["receipt_id"] = tf.receipt_id(receipt["source_event_id"], task_id)
    # A later final reply was claimed, posted, acknowledged and read back later too.
    late = timedelta(seconds=final_offset - 30)
    for row in entry["deliveries"] + entry["task"]["qualification_evidence"]["slack_deliveries"]:
        if row.get("notification_key") == "terminal":
            for key in ("claimed_at", "acknowledged_at", "delivered_at"):
                if row.get(key):
                    row[key] = (datetime.fromisoformat(row[key]) + late).isoformat()
    readback_row = entry["task"]["qualification_evidence"]
    readback_row["task_updated_at"] = (datetime.fromisoformat(readback_row["task_updated_at"]) + late).isoformat()
    if True:  # every final reply is the Director's own terminal rendering of the persisted record
        readback = entry["task"]["qualification_evidence"]
        terminal = next(r for r in readback["slack_deliveries"] if r["notification_key"] == "terminal")
        payload = fixture_render({"task_record": entry["task"], "execution_mode": readback["execution_mode"]},
                                 {"terminal_classification": readback["terminal_classification"],
                                  "reason_code": readback["terminal_reason_code"]},
                                 None, datetime.fromisoformat(terminal["created_at"]))
        entry["messages"][-1]["text"] = payload["text"]
        entry["messages"][-1]["blocks"] = payload["blocks"]
    # The gateway's append-only intake claim for this task's own (re-keyed) intake, digested by its producers.
    readback_row["intake_auth_claims"] = [tf.intake_claim(entry["task"]["intake"], readback_row["task_created_at"])]
    tf.seal(readback_row)  # outcome digests over the re-keyed task and events, as the producer computes them
    return entry


def approval_entry(decided=None, kind="execution", grant=None):  # langgraph_primary.ApprovalKind
    entry = task_entry(APPROVAL_TASK, 30000, offline=False, text="DIRECTOR approve then run")
    readback = entry["task"]["qualification_evidence"]
    # Dispatch follows the execution approval (claimed at 30009, decided at 30010): the assignment is reserved and
    # its attempt runs after it, as the graph resumes only once the owner approved.
    readback["assignments"][0]["reserved_at"] = iso(1789210000 + 30011)
    for event, offset in zip(readback["provider_attempts"], (30012, 30016)):
        event["recorded_at"] = iso(1789210000 + offset)
    # The owner posts at ts(30000); the gateway claims the intake and the task is created a second later (the
    # rebased readback), the approval prompt is enqueued at 30003, the Director restarts at 30003.5 (World) and
    # the graph resumes afterwards: the prompt's post, the decision, the attempts and the terminal reply.
    prompt = ts(30005)
    projection = "sha256:" + "9" * 64
    delivery = {"notification_key": "approval:sha256:" + "8" * 64 + ":" + projection, "projection_digest": projection,
                "client_msg_id": "approval-client-1", "state": "DELIVERED", "created_at": iso(1789210000 + 30003),
                # Claimed before chat.postMessage, acknowledged with the returned ts, then read back.
                "claimed_at": iso(1789210000 + 30004), "acknowledged_at": iso(1789210000 + 30005.5),
                "delivered_at": iso(1789210000 + 30006), "slack_ts": prompt, "readback_attempts": 1,
                "last_error": None, "owner_decision": "approve",
                "owner_decision_at": decided or iso(1789210000 + 30010), "owner_command_id": "owner-command-1"}
    readback["slack_deliveries"].append(delivery)
    entry["deliveries"].append({"task_id": APPROVAL_TASK, **{key: value for key, value in delivery.items()
                                                              if key not in ("created_at", "last_error")}})
    # The prompt is the Director's own rendering of the persisted application record and approval.
    application = {"task_record": entry["task"], "execution_mode": readback["execution_mode"],
                   **({"effect_grant": grant} if grant is not None else {})}
    entry["application"] = application
    payload = fixture_render(application, {"pending_approval": {"kind": kind, "request_digest": "sha256:" + "8" * 64},
                                           "terminal_classification": None},
                             projection, datetime.fromisoformat(delivery["created_at"]))
    assert payload is not None, "the fixture task must render as the Director would"
    entry["messages"].insert(2, {"ts": prompt, "thread_ts": ts(30000), "user": BOT,
                                 "client_msg_id": "approval-client-1", "text": payload["text"],
                                 "blocks": json.loads(json.dumps(payload["blocks"]))})
    return entry


INTAKE_WORKFLOW = json.loads((Path(__file__).resolve().parents[1] / "n8n/workflows/director-intake.json")
                             .read_text(encoding="utf-8"))


def workflow_fixture():
    nodes = json.loads(json.dumps(INTAKE_WORKFLOW["nodes"]))
    for index, node in enumerate(nodes):
        node.update(id=f"deployed-{index}", position=[index * 100, 0])  # deploy-time fields may differ
    return {"active": True, "active_version": "active-version", "stored_version": "active-version", "http_node_count": 1,
            "supported_request": True, "static_request": True, "supported_webhook": True, "direct_connection": True,
            "nodes": nodes, "connections": json.loads(json.dumps(INTAKE_WORKFLOW["connections"])),
            "settings": json.loads(json.dumps(INTAKE_WORKFLOW["settings"])), "pin_data": {},
            # The active version was created, and the workflow last updated (import, activation), with the deployment.
            "active_version_at": "2026-09-12T08:59:30+00:00", "workflow_updated_at": "2026-09-12T08:59:40+00:00"}


def node(workflow_nodes, name):
    return next(item for item in workflow_nodes if item["name"] == name)


class World:
    """One deployment's Docker, Director, n8n and Slack sources; unrouted reads are unavailable."""

    def __init__(self, test=None):
        self._folder = tempfile.TemporaryDirectory(prefix="scorecard-world-")
        if test is not None:
            test.addCleanup(self._folder.cleanup)
        self.root = Path(self._folder.name)
        self.rows = containers() + [item for item in topology() if item["Id"] in (N8N_ID, N8N_DB_ID)]
        # The Director's primary control-plane database (docker-compose.yml langgraph-primary-db).
        self.rows.append({"Id": PRIMARY_DB_ID, "Name": "/edge-engine-director-langgraph-primary-db-1",
                          "Image": "sha256:" + "8" * 64, "Created": "2026-09-12T08:57:00.123456789Z",
                          "State": {"Running": True, "StartedAt": "2026-09-12T08:57:01.000000001Z"},
                          "Config": {"Labels": compose_labels("langgraph-primary-db"), "Env": []},
                          "NetworkSettings": {"Networks": {NETWORK: {"NetworkID": "a" * 64,
                                                                     "Aliases": ["langgraph-primary-db"]}}}})
        self.rows.append({**topology()[1], "Created": "2026-09-12T09:00:00Z"})  # the gateway (kept last), created with the Director
        # The Director process restarted while the approval task waited (approval_entry), after its prompt was enqueued.
        self.rows[0]["State"]["StartedAt"] = iso(1789210000 + 30003.5).replace("+00:00", "Z")
        self.rows[1]["Created"] = "2026-09-12T09:00:00Z"  # the deployment's n8n
        self.commit_tree = "d" * 40
        self.now = WORLD_NOW
        self.until = None  # the collection's end; None means it ends when it starts
        self.readback_captured = WORLD_NOW.isoformat()  # when the Director served each qualification readback
        self.payload = health()
        self.consistency = consistency_fixture()
        self.captures = captures_fixture()
        self.status = status_fixture()
        self.ps_override = None
        self.calls = []
        self.threads, self.tasks, self.deliveries, self.bindings = {}, {}, {}, {}
        self.failing, self.slack_down = set(), False
        self.incomplete = set()
        self.threads[STATUS_TS] = [{"ts": STATUS_TS, "user": BOT, "bot_id": "BBOT123",
                                    "text": "*STATUS — readiness changed*\n• `reachable`: unset → true"}]
        self.history_extra, self.history_hidden = [], set()
        self.history_page = {"has_more": False}  # conversations.history's pagination fields on its one page
        for offset in (100, 150, 200):
            self.threads[ts(offset)] = [
                {"ts": ts(offset), "user": OWNER, "client_msg_id": f"drill-{offset}",
                 "text": f"<@{BOT}> DIRECTOR drill"},
                {"ts": ts(offset + 1), "thread_ts": ts(offset), "user": BOT,
                 "text": "*DIRECTOR — BLOCKED*\nThe Director did not accept the request."}]
        self.bindings[ts(100)] = (404, None)
        self.bindings[ts(150)] = (404, None)
        self.add(task_entry("DIR-LG-5E", 200, text="DIRECTOR drill"), thread=False)
        self.bindings[ts(200)] = (200, "DIR-LG-5E")
        duplicate = self.add(task_entry("DIR-LG-D0", 300))
        duplicate["messages"].append({"ts": ts(302), "thread_ts": ts(300), "user": BOT, "text": "*DIR-LG-D0 — REQUEST RECEIVED*"})
        self.bindings[ts(300)] = (200, "DIR-LG-D0")
        ambiguous = self.add(task_entry("DIR-LG-A0", 400))
        for delivery in ambiguous["deliveries"] + ambiguous["task"]["qualification_evidence"]["slack_deliveries"]:
            delivery["acknowledged_at"] = None
        self.bindings[ts(400)] = (200, "DIR-LG-A0")
        rubric, digest = tf.rubric_fixture()
        self.rubric_path = self.root / "rubric.json"
        self.rubric_path.write_bytes(tf.collector_module.encode(rubric))
        self.trials = []
        for number in range(1, 11):
            self.add(task_entry(f"DIR-LG-7A{number:02X}", 1000 * number, text="DIRECTOR audit trial rubric-sha256:" + digest))
            self.trials.append(ts(1000 * number))
        paid_rubric = {"schema": "director-paid-answer-rubric/v1", "rubric_id": "fixture-paid",
                       "declared_at": "2020-01-01T00:00:00+00:00", "expected_answer_substrings": ["answer is 42"]}
        raw = json.dumps(paid_rubric).encode()
        self.paid_rubric_path = self.root / "paid-rubric.json"
        self.paid_rubric_path.write_bytes(raw)
        self.paid_text = "DIRECTOR What is the answer? rubric-sha256:" + hashlib.sha256(raw).hexdigest()
        self.add(task_entry(PAID_TASK, 20000, offline=False, text=self.paid_text, answer="The audit answer is 42"))
        approval = self.add(approval_entry())
        self.consistency["tasks"][APPROVAL_TASK]["application"] = approval["application"]
        self.candidate_files = {}  # path -> bytes or Exception, overriding the candidate commit's blob
        self.workflow = workflow_fixture()

    def add(self, entry, thread=True):
        task_id = entry["task"]["task_id"]
        self.tasks[task_id], self.deliveries[task_id] = entry["task"], entry["deliveries"]
        if thread:
            self.threads[entry["task"]["intake"]["thread_ts"]] = entry["messages"]
        return entry

    def reply(self, value):
        if value is None:
            raise ValueError("fixture source unavailable")
        if isinstance(value, Exception):
            raise value
        return json.dumps(value).encode()

    def run(self, args, timeout=15):
        args = list(args)
        self.calls.append(args)
        if args[:2] == ["docker", "ps"]:
            wanted = dict(item.split("=", 1)[1].split("=", 1) for item in args if item.startswith("label="))
            if wanted and wanted.get("com.docker.compose.project") != DEPLOYMENT:
                raise AssertionError("docker ps was not filtered to the selected deployment")
            if self.ps_override is not None:
                return "\n".join(self.ps_override).encode()
            rows = [item for item in self.rows if item.get("State", {}).get("Running")
                    and all(sc._labels(item).get(key) == value for key, value in wanted.items())]
            return "\n".join(item["Id"] for item in rows).encode()
        if args[:2] == ["docker", "inspect"]:
            return json.dumps([item for item in self.rows
                               if item["Id"] in args[2:] or item.get("Name", "").lstrip("/") in args[2:]]).encode()
        if args[:2] == ["docker", "exec"] and "director_orchestrator.primary_generation" in args:
            raise AssertionError("candidate code must never execute")
        if args[:2] == ["docker", "exec"] and args[2] == N8N_DB_ID and args[-1] == sc._ACTIVE_INTAKE:
            return self.reply(self.workflow)
        if args[:2] == ["docker", "exec"] and args[2] == N8N_DB_ID and args[-1] == sc._STATUS_EXECUTION:
            return self.reply(self.status)
        if args[:2] == ["git", "-C"] and args[3] == "show":
            return candidate_blob(args[4], self.candidate_files)
        if args[:2] == ["gh", "api"] and args[2] == f"repos/{sc.REPOSITORY}/git/commits/{SHA}":
            return self.reply({"tree": self.commit_tree})
        raise ValueError("unrouted fixture command")

    def handle(self, request):
        if request.method != "GET":
            raise AssertionError("scorecard sources are GET-only")
        if self.slack_down:
            raise httpx.ConnectError("fixture transport down", request=request)
        url = request.url
        if url.host == "slack.com":
            if request.headers["Authorization"] != "Bearer fixture-secret-bot":
                raise AssertionError("Slack read used the wrong credential")
            if url.path == "/api/auth.test":
                return httpx.Response(200, json={"ok": True, "user_id": BOT, "bot_id": "BBOT123"})
            if url.params["channel"] != CHANNEL_FIXTURE:
                raise AssertionError("another channel was read")
            if url.path == "/api/conversations.history":
                if "history" in self.failing:
                    raise httpx.ConnectError("fixture transport failure", request=request)
                low, high = Decimal(url.params["oldest"]), Decimal(url.params["latest"])
                top = [message for key, messages in self.threads.items() for message in messages
                       if message["ts"] == key and key not in self.history_hidden]
                return httpx.Response(200, json={"ok": True, **self.history_page, "messages": [
                    message for message in top + self.history_extra if low <= Decimal(message["ts"]) <= high]})
            thread = url.params["ts"]
            if thread in self.failing:
                raise httpx.ConnectError("fixture transport failure", request=request)
            if thread not in self.threads:
                return httpx.Response(200, json={"ok": False, "error": "thread_not_found"})
            if thread in self.incomplete:  # a cursor that never advances: the readback stays incomplete
                return httpx.Response(200, json={"ok": True, "messages": self.threads[thread], "has_more": True,
                                                 "response_metadata": {"next_cursor": "same"}})
            return httpx.Response(200, json={"ok": True, "messages": self.threads[thread], "has_more": False})
        if not str(url).startswith(API + "/") or request.headers["Authorization"] != "Bearer fixture-director-secret":
            raise AssertionError("Director read left the selected deployment or used the wrong credential")
        parts = url.path.split("/")
        if url.path == "/v1/slack-thread-bindings":
            thread = url.params["thread_ts"]
            if thread in self.failing:
                raise httpx.ConnectError("fixture transport failure", request=request)
            status, task_id = self.bindings.get(thread, (404, None))
            body = ({"channel_id": url.params["channel_id"], "thread_ts": thread, "task_id": task_id}
                    if status == 200 else {"detail": "fixture"})
            return httpx.Response(status, json=body)
        if url.path.startswith("/v1/tasks/") and parts[3] in self.tasks:
            task = json.loads(json.dumps(self.tasks[parts[3]]))
            if isinstance(task.get("qualification_evidence"), dict) and self.readback_captured is not None:
                # The readback is a live REPEATABLE READ snapshot taken when the API serves it (langgraph_postgres).
                task["qualification_evidence"]["captured_at"] = self.readback_captured
            return httpx.Response(200, json=task, headers={
                "x-task-engine-owner": "langgraph", "x-primary-projection-digest": "fixture-digest"})
        if url.path.endswith("/deliveries") and parts[4] in self.deliveries:
            return httpx.Response(200, json=self.deliveries[parts[4]])
        return httpx.Response(404, json={"detail": "fixture"})

    def slack(self, runtime, channel, owner=None):
        reader = REAL_SLACK_THREADS(runtime, channel, owner, client=httpx.Client(
            transport=httpx.MockTransport(self.handle), follow_redirects=False, trust_env=False))
        # Rule fixtures supply synthetic records, including intentionally malformed
        # ones. They do not exercise or attest the real trusted-store consumer;
        # TrustedTaskConsumerTests and the sanctioned TLS fixture cover that path.
        reader.task = lambda task: reader.reads.get(API + "/v1/tasks/" + task,
                                                   params=dict(reader.m.READBACK_QUERY))
        reader.deliveries = lambda task: reader.reads.get(API + "/v1/primary/tasks/" + task + "/deliveries")[0]
        def binding(thread):
            status, body = reader._get(API + "/v1/slack-thread-bindings",
                {"channel_id": reader.channel, "thread_ts": thread}, reader.env["ORCHESTRATOR_SHARED_SECRET"])
            if status in (404, 409):
                return None if status == 404 else "AMBIGUOUS"
            if status != 200:
                raise ValueError("fixture binding unavailable")
            value = json.loads(body)
            task = value.get("task_id") if isinstance(value, dict) else None
            if (not isinstance(task, str) or not sc._TASK.fullmatch(task)
                    or value.get("channel_id") != reader.channel or value.get("thread_ts") != thread):
                raise ValueError("fixture binding does not echo the selected thread")
            return task
        reader.binding = binding
        return reader

    def observe(self, only_deployment=False, evaluate_rules=False, **options):
        selected = dict(deployment=DEPLOYMENT)
        if not only_deployment:
            selected.update(channel=CHANNEL_FIXTURE, owner=OWNER, approval_task=APPROVAL_TASK, trials=list(self.trials),
                            gateway=GATEWAY, topology=False,
                            rubric_path=self.rubric_path, paid_thread=ts(20000), paid_rubric_path=self.paid_rubric_path,
                            drill_threads={"refusal-4xx": ts(100), "reserved-5xx": ts(200), "transport-failure": ts(150),
                                           "duplicate-input": ts(300), "ambiguous-post": ts(400)})
        selected.update(options)
        opened = []

        def health_server(request):
            # /health, read through the one bounded HTTP path (bounded_get), never redirected.
            opened.append(str(request.url))
            return httpx.Response(200, json=self.payload)

        def client():
            return httpx.Client(transport=httpx.MockTransport(health_server), follow_redirects=False, trust_env=False)

        runtime_seen = []
        original_runtime = sc._runtime

        def runtime_probe(*args, **kwargs):
            result = original_runtime(*args, **kwargs)
            runtime_seen.append(result[1])
            return result

        with patch.object(sc, "_runtime", side_effect=runtime_probe), \
                patch.object(sc, "_run_bytes", side_effect=self.run), patch.object(sc, "_http_client", client), \
                patch.object(sc, "_SlackThreads", side_effect=self.slack), \
                patch.object(sc, "_trusted_collection", return_value=(self.consistency, self.captures)) \
                if evaluate_rules else nullcontext(), \
                patch.object(sc, "_CONTAINED_RUNTIME", tuple(
                    key for key in sc._CONTAINED_RUNTIME
                    if not evaluate_rules or key not in ("01", "02", "03", "04", "05", "09", "19"))):
            observations = sc.collect(SHA, now=self.now, until=self.until, **selected)
            if evaluate_rules and runtime_seen:
                observations = self.evaluate_rules(runtime_seen[0], selected, observations)
        self.opened = opened
        return observations

    def evaluate_rules(self, runtime, selected, observations):
        """Direct evaluator fixtures only: these reports never enter live collection."""
        at = self.now
        found = {item.check_id: item for item in observations}

        def put(items):
            found.update((item.check_id, item) for item in items)

        consistency, captures = self.consistency, self.captures
        if consistency is not None and not runtime.read_in_window(consistency.get("captured_at")):
            consistency = None
        if captures is not None and not runtime.read_in_window(captures.get("observed_at")):
            captures = None
        if consistency is None:
            captures = None
        try:
            runtime = sc._gateway_bound(runtime, selected["gateway"])
            verified, activated = sc._intake_route_verified(runtime, selected["gateway"])
            if activated is not None:
                runtime = dataclasses.replace(runtime, created_at=max(runtime.created_at, activated))
        except (KeyError, *sc._SOURCE_ERRORS):
            verified = None
        t = None
        paid = None
        try:
            if selected.get("channel") is not None:
                try:
                    t = self.slack(runtime, selected["channel"], selected.get("owner"))
                except sc._SOURCE_ERRORS:
                    pass
            if t is not None:
                try:
                    put([sc._trial_observation(at, runtime, t, selected.get("trials"),
                                               selected.get("rubric_path"))])
                except sc._SOURCE_ERRORS:
                    pass
                if selected.get("paid_thread") is not None:
                    try:
                        paid = sc._paid_facts(t, selected["paid_thread"], runtime.runtime_sha)
                    except sc._SOURCE_ERRORS:
                        pass
                if selected.get("approval_task") is None:
                    put([sc._observation(key, None, "No --approval-task was supplied.",
                                         sc._SLACK_SOURCE, {}, at, **runtime.binding)
                         for key in ("06", "08")])
                else:
                    try:
                        put(sc._approval_observations(at, runtime, t, selected["approval_task"], consistency))
                    except sc._SOURCE_ERRORS:
                        pass
            put([sc._reconciliation_observation(at, runtime, consistency)])
            put(sc._capture_observations(at, runtime, captures, paid))
            put([sc._acceptance_observation(at, SHA, consistency)])
            put([sc._paid_observation(at, runtime, paid, selected.get("paid_rubric_path"),
                                     consistency, t.m.LABEL if t is not None else "")])
            if t is not None and verified is True:
                try:
                    put([sc._trial_observation(at, runtime, t, selected.get("trials"), selected.get("rubric_path"))])
                except sc._SOURCE_ERRORS:
                    pass
            cost = sc._settled_cost(consistency, paid)[0] if paid is not None else None
            put([sc._monetary_observation(at, runtime, paid, consistency, cost)])
            if verified is not True or t is None:
                for key in ("08", "10", "20"):
                    found[key] = next(item for item in observations if item.check_id == key)
            if t is None:
                found["11"] = next(item for item in observations if item.check_id == "11")
        finally:
            if t is not None:
                t.close()
        return sc._finalize(list(found.values()), self.until or self.now)

    def report(self, **options):
        return sc.score(SHA, self.observe(**options), now=self.until or self.now, runtime_sha=SHA, image_id=IMAGE)

    def state(self, check, **options):
        return row(self.report(**options), check)["status"]


def runtime_observations(payload=None, rows=None, *, evaluate_rules=False):
    # Substitute external I/O, not the score's trust check or predicates.
    world = World()
    world.payload = payload if payload is not None else health()
    world.consistency = world.captures = None
    world.now = NOW
    if rows is not None:
        world.rows = rows
    try:
        return world.observe(only_deployment=True, evaluate_rules=evaluate_rules)
    finally:
        world._folder.cleanup()


def run(mode="offline", number=1):
    return {"run_id": str(number), "mode": mode, "actual_owner_event": True,
            "correctness_verified": True, "task_count": 1, "terminal_reply_count": 1,
            "wall_seconds": 40.0, "owner_pause_seconds": 10.0, "machine_seconds": 30.0,
            "actual_cost_usd": 0 if mode == "offline" else 0.4,
            "ambiguous_effects": 0, "delivery_ambiguous": False,
            "operational_provider_attempts": 0 if mode == "offline" else 1,
            "simulation_label": "SIMULATION — NO PROVIDER INTERACTION",
            "runtime_sha": SHA, "image_id": IMAGE,
            "cost_basis": "simulation_zero_calls" if mode == "offline" else "correlated_actual_charges"}


def qualify(records, mode="offline"):
    return sc.evaluate_run_records(records, mode=mode, runtime_sha=SHA, image_id=IMAGE)[0]


