TRUSTED_CI = b"name: CI\njobs: {}\n"
EVALUATOR = "e" * 40  # the owner-pinned evaluator revision
EVALUATED = {"version": "director-cli-release-descriptor/v1", "releases": [], "evaluator_sha": EVALUATOR}


def workflow_contents(content):
    """The GitHub contents API's answer for one file: base64 content under its git blob id."""
    import base64
    return {"type": "file", "encoding": "base64", "content": base64.b64encode(content).decode(),
            "sha": hashlib.sha1(b"blob %d\0" % len(content) + content).hexdigest()}


def gh_runs(jobs_by_run, paths=None, compare=None, size=100, total=None, workflows=None):
    """Runs come newest first; every run is ci.yml unless ``paths`` names another workflow. ``workflows`` maps a ref
    to its ci.yml bytes (default: the candidate's ci.yml is main's)."""
    def query(args, timeout=15):
        if args[0] != "gh":
            raise ValueError("offline")
        if "/contents/" in args[2]:
            ref = args[2].split("?ref=")[1]
            return workflow_contents((workflows or {}).get(ref, TRUSTED_CI))
        if "/compare/" in args[2]:
            return {"status": (compare or {}).get(args[2].split("/compare/")[1], "ahead")}
        if "/jobs?" in args[-1]:
            jobs = jobs_by_run[int(args[-1].split("/runs/")[1].split("/")[0])]
            return {"total_count": len(jobs), "jobs": jobs}
        if "head_sha=" + SHA not in args[-1]:
            raise AssertionError("CI query is not bound to the exact head")
        runs = [{"id": run_id, "path": (paths or {}).get(run_id, sc.CI_WORKFLOW)} for run_id in jobs_by_run]
        page = int(args[-1].split("&page=")[1]) if "&page=" in args[-1] else 1  # GitHub's default page
        return {"total_count": len(runs) if total is None else total, "workflow_runs": runs[(page - 1) * size:page * size]}
    return query


def ci_jobs(steps=True, failed=()):
    return [{"name": name, "conclusion": "failure" if name in failed else "success",
             "steps": [{"name": "run", "status": "completed", "conclusion": "success"}] if steps else []}
            for name in sc.CI_JOBS]


def replica_receipt(key, candidate=SHA, head_failures=("tests.test_fixture.T.test_known",), head_tests_run=3000):
    document = {"schema": "director-ci-local-replica/v1", "repository": sc.REPOSITORY, "candidate_sha": candidate,
                "base_sha": OTHER, "produced_at": (NOW - timedelta(hours=1)).isoformat(),
                "lanes": [{"lane": lane, "head_tests_run": head_tests_run, "base_tests_run": 2990,
                           "head_failures": list(head_failures), "base_failures": ["tests.test_fixture.T.test_known"],
                           "command_sha256": "f" * 64} for lane in ("windows-postgres-lane", "ubuntu-replica")]}
    signed = json.dumps(document, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False).encode()
    return {"document": document, "signature": key.sign(signed).hex()}


def resign(key, envelope):
    signed = json.dumps(envelope["document"], sort_keys=True, separators=(",", ":"), ensure_ascii=True,
                        allow_nan=False).encode()
    return {"document": envelope["document"], "signature": key.sign(signed).hex()}


_EVALUATOR_BOOTSTRAP_DIR = tempfile.TemporaryDirectory(prefix="evaluator-bootstrap-")


def _write_evaluator_bootstrap():
    # A plain evaluator-side bootstrap script (hop2): loads an archived director-scorecard.py by path, replaces
    # only its OS account lookup (and, where present, primary_scorecard_evidence's) with the fixture home, after
    # exec so the file's own `def account_home():` cannot clobber the fixture, then calls main() the same way the
    # real launcher's own bootstrap does. Computed once, as a plain file, so no test ever nests multiple levels
    # of string-escaped Python source.
    source = ("import importlib\n"
             "import importlib.util\n"
             "import sys\n"
             "from pathlib import Path\n"
             "\n"
             "sys.path.insert(0, sys.argv[1])\n"
             "spec = importlib.util.spec_from_file_location('director_scorecard_cli', sys.argv[2])\n"
             "cli = importlib.util.module_from_spec(spec)\n"
             "spec.loader.exec_module(cli)\n"
             "home = Path(sys.argv[3])\n"
             "cli.account_home = lambda: home\n"
             "\n"
             "try:\n"
             "    pse = importlib.import_module('director_orchestrator.primary_scorecard_evidence')\n"
             "except ImportError:\n"
             "    pse = None\n"
             "if pse is not None:\n"
             "    pse.account_home = lambda: home\n"
             "\n"
             "# completion_scorecard._launcher() loads a *fresh* scorecard-launcher.py module every call (by\n"
             "# design, uncached); patch its account_home the same way, right after that fresh module executes.\n"
             "_real_spec_from_file_location = importlib.util.spec_from_file_location\n"
             "\n"
             "\n"
             "class _PatchedLauncherLoader:\n"
             "    def __init__(self, real_loader):\n"
             "        self._real_loader = real_loader\n"
             "\n"
             "    def create_module(self, spec):\n"
             "        return self._real_loader.create_module(spec)\n"
             "\n"
             "    def exec_module(self, module):\n"
             "        self._real_loader.exec_module(module)\n"
             "        module.account_home = lambda: home\n"
             "\n"
             "    def __getattr__(self, name):\n"
             "        return getattr(self._real_loader, name)\n"
             "\n"
             "\n"
             "def _patched_spec_from_file_location(name, path, *args, **kwargs):\n"
             "    inner = _real_spec_from_file_location(name, path, *args, **kwargs)\n"
             "    if name == 'scorecard_launcher':\n"
             "        inner.loader = _PatchedLauncherLoader(inner.loader)\n"
             "    return inner\n"
             "\n"
             "\n"
             "importlib.util.spec_from_file_location = _patched_spec_from_file_location\n"
             "sys.argv = ['director-scorecard.py'] + sys.argv[4:]\n"
             "if hasattr(cli, 'main'):\n"
             "    raise SystemExit(cli.main())\n")
    folder = Path(_EVALUATOR_BOOTSTRAP_DIR.name)
    script = folder / "evaluator_bootstrap.py"
    script.write_text(source, encoding="utf-8")
    return script


EVALUATOR_BOOTSTRAP_SCRIPT = _write_evaluator_bootstrap()


def evaluator_bootstrap_command(src, script, home, *arguments, isolated=True):
    """Run the given director-scorecard.py file directly, exactly as the launcher's hop2 would, with only its (and
    the evidence module's) OS account lookup replaced by the fixture home; proves a boundary strictly inside the
    launcher-started trust gate (for example nonce reuse), distinct from whether that gate itself was passed."""
    return [sys.executable, *(["-I"] if isolated else []), "-B", str(EVALUATOR_BOOTSTRAP_SCRIPT),
            str(src), str(script), str(home), *[str(argument) for argument in arguments]]


def installed_launcher_command(installed, home, *arguments, isolated=True):
    """Run the installed launcher file as its own module with only its OS account lookup replaced by the fixture
    home; HOME/USERPROFILE cannot move the owner root, so tests never read or write the real one. When the
    launcher spawns its evaluator subprocess (hop2), this also substitutes EVALUATOR_BOOTSTRAP_SCRIPT for it, so
    the real launcher -> evaluator flow runs end to end without either hop ever touching the real OS account."""
    bootstrap = (
        "import importlib.util, sys\n"
        "from pathlib import Path\n"
        "spec = importlib.util.spec_from_file_location('installed_launcher', sys.argv[1])\n"
        "module = importlib.util.module_from_spec(spec)\n"
        "spec.loader.exec_module(module)\n"
        "home = Path(sys.argv[2])\n"
        "module.account_home = lambda: home\n"
        "real_run = module.subprocess.run\n"
        "\n"
        "\n"
        "def _patched_run(cmd, **options):\n"
        "    if (isinstance(cmd, list) and len(cmd) > 6 and cmd[3] == '-c' and\n"
        "            isinstance(cmd[4], str) and 'runpy' in cmd[4]):\n"
        f"        cmd = [cmd[0], cmd[1], cmd[2], {str(EVALUATOR_BOOTSTRAP_SCRIPT)!r}, cmd[5], cmd[6], str(home),\n"
        "               *cmd[7:]]\n"
        "    return real_run(cmd, **options)\n"
        "\n"
        "\n"
        "module.subprocess.run = _patched_run\n"
        "raise SystemExit(module.main(sys.argv[3:]))\n"
    )
    return [sys.executable, *(["-I"] if isolated else []), "-c", bootstrap, str(installed), str(home),
            *[str(argument) for argument in arguments]]


class OwnerAccountLookupTests(unittest.TestCase):
    """Missing POSIX account records refuse every consumer without trusting environment fallbacks."""

    def setUp(self):
        self.launcher = sc._launcher()
        source = Path(__file__).resolve().parents[1] / "scripts" / "director-scorecard.py"
        spec = importlib.util.spec_from_file_location("missing_uid_scorecard", source)
        self.cli = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(self.cli)
        self.uid = 424242
        self.lookup = Mock(side_effect=KeyError(self.uid))
        stack = self.enterContext(ExitStack())
        stack.enter_context(patch.dict(sys.modules, {"pwd": SimpleNamespace(getpwuid=self.lookup)}))
        unavailable = SimpleNamespace(name="posix", geteuid=lambda: self.uid, environ={
            "HOME": "/caller/home", "USERPROFILE": "/caller/profile",
            pse.OWNER_HOME_ENV: "/caller/owner", pse.DESCRIPTOR_ENV: "a" * 64,
        })
        for module in (self.launcher, self.cli, pse):
            stack.enter_context(patch.object(module, "os", unavailable))

    def test_missing_uid_normalizes_all_account_lookups(self):
        for module in (self.launcher, self.cli, pse):
            with self.subTest(module=module.__name__), self.assertRaisesRegex(OSError, "no passwd entry"):
                module.account_home()
        self.assertEqual(self.lookup.call_count, 3)
        self.lookup.assert_called_with(self.uid)

    def test_missing_uid_leaves_descriptor_and_authority_consumers_unavailable(self):
        self.assertIsNone(self.cli.release_descriptor())
        self.assertEqual(self.cli.launch_refusal(), "evaluator revision not pinned")
        self.assertIsNone(pse.owner_home())
        self.assertIsNone(pse.cli_release_descriptor())
        with patch.object(sc, "CI_REPLICA_KEY", None):
            self.assertIsNone(sc._ci_replica_key())

    def test_missing_uid_leaves_the_score_unattested(self):
        with patch.object(sc, "_launcher", return_value=self.launcher):
            report = sc.score("a" * 40, [])
        self.assertFalse(report["attested"])
        self.assertEqual(report["passed"], "UNATTESTED")
        self.assertFalse(report["activation_authorized"])

    def test_missing_uid_launcher_returns_clean_refusal(self):
        stderr = io.StringIO()
        with patch.object(self.launcher, "sys", SimpleNamespace(
                flags=SimpleNamespace(isolated=True), stderr=stderr)):
            self.assertEqual(self.launcher.main([]), 2)
        self.assertIn("the owner account home could not be resolved", stderr.getvalue())
        self.assertNotIn("Traceback", stderr.getvalue())


class PosixAccountLookupTests(unittest.TestCase):
    """Copilot review of #420: a POSIX effective UID with no passwd entry (or an unusable home) must fail closed as
    OSError, which every caller already refuses on, never as a KeyError traceback."""

    def modules(self):
        import importlib.util
        root = Path(__file__).resolve().parents[1]
        from director_orchestrator import primary_scorecard_evidence as evidence
        found = {"evidence": evidence.account_home}
        for name, script in (("launcher", "scorecard-launcher.py"), ("evaluator", "director-scorecard.py")):
            spec = importlib.util.spec_from_file_location("posix_lookup_" + name, root / "scripts" / script)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            found[name] = module.account_home
        return found

    def lookup(self, function, entry):
        fake = types.SimpleNamespace(getpwuid=entry)
        with patch.object(os, "name", "posix"), patch.object(os, "geteuid", create=True, return_value=4242),                 patch.dict(sys.modules, {"pwd": fake}):
            return function()

    def test_missing_passwd_entry_and_unusable_home_are_oserror(self):
        def missing(uid):
            raise KeyError(uid)
        for name, function in self.modules().items():
            for label, entry in (("missing", missing),
                                 ("empty", lambda uid: types.SimpleNamespace(pw_dir="")),
                                 ("relative", lambda uid: types.SimpleNamespace(pw_dir="home/owner"))):
                with self.subTest(module=name, case=label), self.assertRaises(OSError):
                    self.lookup(function, entry)

    def test_a_valid_passwd_entry_is_the_account_home(self):
        for name, function in self.modules().items():
            with self.subTest(module=name):
                home = self.lookup(function, lambda uid: types.SimpleNamespace(pw_dir=os.path.abspath(os.sep + "home")))
                self.assertEqual(os.path.abspath(os.sep + "home"), str(home))


class ScorecardGitTrustTests(unittest.TestCase):
    """Real object databases: replacement siblings must never supply executable evaluator bytes."""

    def setUp(self):
        self.folder = tempfile.TemporaryDirectory()
        self.addCleanup(self.folder.cleanup)
        base = Path(self.folder.name)
        self.repo, self.home, self.outside = base / "repo", base / "home", base / "outside"
        for path in (self.repo / "scripts", self.home / ".director-scorecard", self.outside):
            path.mkdir(parents=True)
        source = Path(__file__).resolve().parents[1]
        self.modules = {}
        for name in ("scorecard-launcher", "director-scorecard"):
            spec = importlib.util.spec_from_file_location(name, source / "scripts" / f"{name}.py")
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            self.modules[name] = module
        self.launcher = self.modules["scorecard-launcher"]
        self.installed = self.home / ".director-scorecard" / "launcher.py"
        self.installed.write_bytes((source / "scripts/scorecard-launcher.py").read_bytes())
        self.git("init", "-q")
        self.git("commit", "--allow-empty", "-qm", "parent")
        self.parent = self.git("rev-parse", "HEAD").decode().strip()
        self.script = self.repo / "scripts" / "director-scorecard.py"
        self.script.write_text(
            "import json, os\nfrom pathlib import Path\n"
            "receipt = Path(os.environ['DIRECTOR_SCORECARD_OWNER_HOME']) / '.director-scorecard' / 'attestations' / (os.environ['DIRECTOR_SCORECARD_NONCE'] + '.json')\n"
            "attestation = json.loads(receipt.read_bytes())['attestation']\n"
            "Path(os.environ['DIRECTOR_SCORECARD_RESULT']).write_text(json.dumps({'attested': True, 'attestation': attestation}))\n"
            "print('clean evaluator reached')\n", encoding="utf-8")
        self.git("add", ".")
        self.git("commit", "-qm", "evaluator")
        self.pin = self.git("rev-parse", "HEAD").decode().strip()
        self.git("update-ref", "refs/remotes/github/main", self.pin)
        self.descriptor = self.home / ".director-scorecard" / "release-descriptor.json"
        self.descriptor.write_text(json.dumps({"version": self.launcher.DESCRIPTOR_VERSION,
                                              "evaluator_sha": self.pin}), encoding="utf-8")
        self.marker = self.outside / "malicious-executed"

    def git(self, *arguments):
        # Adding the real src tree on a busy Windows runner exceeds 30s.
        return subprocess.run(["git", "--no-replace-objects", "-C", str(self.repo),
                               "-c", "user.email=fixture@example.test", "-c", "user.name=fixture", *arguments],
                              env=self.launcher._git_environment(), check=True, capture_output=True,
                              timeout=120).stdout

    def python_environment(self):
        # Git needs no native Python extension libraries; the CI interpreter does.
        env = self.launcher._git_environment()
        if "LD_LIBRARY_PATH" in os.environ:
            env["LD_LIBRARY_PATH"] = os.environ["LD_LIBRARY_PATH"]
        return env

    def run_launcher(self, extra_env=None, arguments=(), *, target=None):
        # HOME/USERPROFILE no longer move the owner root (#287 item 34); only an in-process
        # substitute for the OS lookup does, so the fixture root never touches the real one.
        env = {**self.python_environment(), **(extra_env or {})}
        return subprocess.run(installed_launcher_command(self.installed, self.home,
                                                         str(self.repo) if target is None else target, *arguments),
                              env=env, cwd=self.outside, capture_output=True, text=True, timeout=120)

    def owner_home(self):
        """This process's launcher module, the scorecard's copy and the evidence module all see the fixture home
        as the account home."""
        stack = ExitStack()
        stack.enter_context(patch.object(self.launcher, "account_home", return_value=self.home))
        stack.enter_context(patch.object(sc, "_launcher", return_value=self.launcher))
        stack.enter_context(patch.object(pse, "account_home", return_value=self.home))
        return stack

    def descriptor_digest(self):
        return hashlib.sha256(self.descriptor.read_bytes()).hexdigest()

    def assert_metadata_refused(self, reason):
        result = self.run_launcher()
        self.assertEqual(result.returncode, 2, result.stderr)
        self.assertIn(reason, result.stderr)
        self.assertNotIn("clean evaluator reached", result.stdout)
        self.assertFalse(self.marker.exists())
        cli = self.modules["director-scorecard"]
        launched = {cli.TREE_ENV: str(cli.ROOT), cli.REPO_ENV: str(self.repo), cli.SHA_ENV: self.pin,
                    cli.DESCRIPTOR_ENV: self.descriptor_digest()}
        with patch.dict(os.environ, launched):
            self.assertIn(reason, cli.launch_refusal(cli.ROOT, self.descriptor))
        with self.assertRaisesRegex(ValueError, reason):
            sc._run_bytes(["git", "-C", str(self.repo), "diff", "--name-only", self.parent, self.pin])
        with patch.dict(os.environ, {"DIRECTOR_SCORECARD_REPO": str(self.repo)}):
            self.assertIsNone(sc._candidate_blob(self.pin, "scripts/director-scorecard.py"))

    def test_replace_ref_to_sibling_commit_refused_without_execution(self):
        self.script.write_text(f"from pathlib import Path\nPath({str(self.marker)!r}).write_text('executed')\n",
                               encoding="utf-8")
        self.git("add", ".")
        malicious_tree = self.git("write-tree").decode().strip()
        sibling = self.git("commit-tree", malicious_tree, "-p", self.parent, "-m", "malicious sibling").decode().strip()
        self.assertEqual(self.git("rev-parse", f"{sibling}^"), self.git("rev-parse", f"{self.pin}^"))
        self.git("update-ref", f"refs/replace/{self.pin}", sibling)
        self.assert_metadata_refused("replace refs")
        # Even below the refusal gate the primitive resolves the original object's tree.
        self.assertEqual(self.launcher._git(self.repo, "rev-parse", f"{self.pin}^{{tree}}"),
                         self.git("rev-parse", f"{self.pin}^{{tree}}"))

    def test_common_directory_grafts_refused_from_linked_worktree(self):
        common = Path(os.fsdecode(self.git("rev-parse", "--path-format=absolute", "--git-common-dir")).strip())
        linked = self.outside / "linked"
        self.git("worktree", "add", "--detach", str(linked), self.pin)
        (common / "info" / "grafts").write_text(self.pin + "\n", encoding="ascii")
        self.repo = linked
        self.assert_metadata_refused("grafts metadata")

    def test_clean_pin_launches_and_git_environment_overrides_are_ignored(self):
        hostile = {name: "invalid-fixture-value" for name in (
            "GIT_DIR", "GIT_WORK_TREE", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES",
            "GIT_REPLACE_REF_BASE", "GIT_NAMESPACE", "GIT_CONFIG", "GIT_CONFIG_PARAMETERS",
            "GIT_CONFIG_SYSTEM", "GIT_GRAFT_FILE")}
        hostile.update(GIT_NO_REPLACE_OBJECTS="0", GIT_CONFIG_COUNT="1",
                       GIT_CONFIG_KEY_0="core.bare", GIT_CONFIG_VALUE_0="true")
        result = self.run_launcher(hostile)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout.strip(), "clean evaluator reached")
        cli = self.modules["director-scorecard"]
        with patch.dict(os.environ, {**hostile, cli.TREE_ENV: str(cli.ROOT), cli.REPO_ENV: str(self.repo),
                                     cli.SHA_ENV: self.pin, cli.DESCRIPTOR_ENV: self.descriptor_digest()}):
            self.assertIsNone(cli.launch_refusal(cli.ROOT, self.descriptor))
            self.assertEqual(sc._run_bytes(["git", "-C", str(self.repo), "show",
                                           f"{self.pin}:scripts/director-scorecard.py"]), self.script.read_bytes())

    def test_home_environment_cannot_relocate_the_owner_root_287_34(self):
        real = self.launcher.account_home()
        with patch.dict(os.environ, {"HOME": str(self.home), "USERPROFILE": str(self.home),
                                     "HOMEDRIVE": "Z:", "HOMEPATH": "\\attacker"}):
            self.assertEqual(self.launcher.account_home(), real)
            self.assertNotEqual(self.launcher.owner_root(), self.home / ".director-scorecard")
        # A copied launcher, fake descriptor and attestation dir under an attacker HOME is not the installed launcher.
        copied = subprocess.run([sys.executable, "-I", str(self.installed), str(self.repo)],
                                env={**self.python_environment(), "HOME": str(self.home), "USERPROFILE": str(self.home)},
                                cwd=self.outside, capture_output=True, text=True, timeout=60)
        self.assertEqual(copied.returncode, 2, copied.stderr)
        self.assertIn("use the owner-installed launcher", copied.stderr)
        self.assertNotIn("clean evaluator reached", copied.stdout)

    def test_any_descriptor_change_during_a_launch_voids_the_report_287_33(self):
        run = subprocess.run
        document = json.loads(self.descriptor.read_text())

        def launch(arguments, **options):
            if arguments[0] == "git":
                return run(arguments, **options)
            env = options["env"]
            self.assertEqual(env[self.launcher.DESCRIPTOR_ENV], digest)
            self.assertEqual(env[self.launcher.OWNER_HOME_ENV], str(self.home))
            receipt = json.loads(self.launcher._receipt_path(env[self.launcher.NONCE_ENV]).read_bytes())
            Path(env["DIRECTOR_SCORECARD_RESULT"]).write_text(json.dumps(
                {"attested": True, "attestation": receipt["attestation"]}))
            # Same evaluator pin; only another owner field changes mid-run.
            self.descriptor.write_text(json.dumps({**document, "security_base_sha": "c" * 40}))
            return subprocess.CompletedProcess(arguments, 0)

        digest = self.descriptor_digest()
        with patch.object(self.launcher.subprocess, "run", side_effect=launch), \
                patch.object(self.launcher.Path, "cwd", return_value=self.outside), \
                patch.object(self.launcher, "account_home", return_value=self.home), \
                patch.object(self.launcher, "__file__", str(self.installed)), \
                redirect_stderr(io.StringIO()) as stderr:
            self.assertEqual(self.launcher.launch(self.repo, [], self.descriptor), 2)
        self.assertIn(self.launcher.UNATTESTED, stderr.getvalue())

    def test_evaluator_reads_owner_files_only_as_the_launcher_pinned_them_287_33(self):
        from director_orchestrator import primary_scorecard_evidence as evidence
        cli = self.modules["director-scorecard"]
        digest = self.descriptor_digest()
        handed = {evidence.OWNER_HOME_ENV: str(self.home), evidence.DESCRIPTOR_ENV: digest}
        with self.owner_home(), patch.object(cli, "account_home", return_value=self.home), \
                patch.dict(os.environ, handed):
            self.assertEqual(evidence.cli_release_descriptor()["evaluator_sha"], self.pin)
            self.assertEqual(cli.pinned_evaluator(), self.pin)
        for broken in ({evidence.DESCRIPTOR_ENV: "0" * 64}, {evidence.OWNER_HOME_ENV: "relative/home"}):
            with self.subTest(broken=broken), patch.dict(os.environ, {**handed, **broken}):
                self.assertIsNone(evidence.cli_release_descriptor())
        with patch.dict(os.environ, {**handed, evidence.DESCRIPTOR_ENV: "0" * 64}):
            self.assertIsNone(cli.pinned_evaluator())
        # Without the launcher's hand-over, no owner file is read at all.
        clean = {key: value for key, value in os.environ.items()
                 if key not in (evidence.OWNER_HOME_ENV, evidence.DESCRIPTOR_ENV)}
        with patch.dict(os.environ, clean, clear=True):
            self.assertIsNone(evidence.owner_home())
            self.assertIsNone(evidence.cli_release_descriptor())
            self.assertIsNone(cli.pinned_evaluator())
            self.assertIsNone(sc._ci_replica_key())

    def test_metadata_probe_errors_fail_closed(self):
        for name, module in self.modules.items():
            with self.subTest(module=name), patch.object(module, "_git", side_effect=subprocess.TimeoutExpired("git", 1)):
                with self.assertRaises(subprocess.SubprocessError):
                    module._reject_git_metadata(self.repo)
        with self.assertRaises((OSError, ValueError, subprocess.SubprocessError)):
            sc._run_bytes(["git", "-C", str(self.outside / "missing"), "show", self.pin])

    def test_archive_uses_the_verified_tree_id(self):
        tree_id = self.git("rev-parse", f"{self.pin}^{{tree}}").decode().strip()
        run = subprocess.run

        def launch(arguments, **options):
            if arguments[0] == "git":
                return run(arguments, **options)
            env = options["env"]
            receipt = json.loads(self.launcher._receipt_path(env[self.launcher.NONCE_ENV]).read_bytes())
            Path(env["DIRECTOR_SCORECARD_RESULT"]).write_text(json.dumps(
                {"attested": True, "attestation": receipt["attestation"]}))
            return subprocess.CompletedProcess(arguments, 0)

        with patch.object(self.launcher, "_git", wraps=self.launcher._git) as git, \
                patch.object(self.launcher.subprocess, "run", side_effect=launch), \
                patch.object(self.launcher.Path, "cwd", return_value=self.outside), \
                patch.object(self.launcher, "account_home", return_value=self.home), \
                patch.object(self.launcher, "__file__", str(self.installed)):
            self.assertEqual(self.launcher.launch(self.repo, [], self.descriptor), 0)
        git.assert_any_call(self.repo, "rev-parse", "--verify", f"{self.pin}^{{tree}}")
        git.assert_any_call(self.repo, "archive", "--format=tar", tree_id)
        self.assertNotEqual(tree_id, self.pin)

    def test_launcher_attests_real_report_and_consumers_reject_tampering(self):
        import shutil

        source = Path(__file__).resolve().parents[1]
        shutil.copytree(source / "src", self.repo / "src", ignore=shutil.ignore_patterns("__pycache__"))
        for name in ("director-scorecard.py", "scorecard-launcher.py"):
            (self.repo / "scripts" / name).write_bytes((source / "scripts" / name).read_bytes())
        script = self.repo / "scripts" / "director-scorecard.py"
        original = script.read_bytes()
        script.write_bytes(
            ("import ctypes, httpx, site, sys\n"
             "assert sys.flags.isolated and sys.flags.no_user_site\n"
             "assert site.ENABLE_USER_SITE is False\n"
             f"assert sys.prefix == {sys.prefix!r}\n").encode() + original)
        self.git("add", ".")
        self.git("commit", "-qm", "real evaluator")
        self.pin = self.git("rev-parse", "HEAD").decode().strip()
        self.git("update-ref", "refs/remotes/github/main", self.pin)
        self.descriptor.write_text(json.dumps({"version": self.launcher.DESCRIPTOR_VERSION,
                                              "evaluator_sha": self.pin}))
        output = self.outside / "reports"
        arguments = ["--candidate", self.pin, "--output-dir", str(output)]
        poison = self.outside / "poison"
        poison.mkdir()
        (poison / "ctypes.py").write_text("raise RuntimeError('caller path imported')\n")
        (poison / "sitecustomize.py").write_text("raise RuntimeError('caller site imported')\n")
        launched = self.run_launcher(
            {"PYTHONPATH": str(poison), "PYTHONUSERBASE": str(poison)}, arguments=arguments)
        self.assertEqual(launched.returncode, 0, launched.stderr)
        report_path = output / "completion-scorecard.json"
        report = json.loads(report_path.read_bytes())
        self.assertIs(report["attested"], True)
        self.assertEqual(report["passed"], 0)
        self.assertEqual(report["attestation"]["tree_id"],
                         self.git("rev-parse", f"{self.pin}^{{tree}}").decode().strip())
        self.assertEqual(report["attestation"]["launcher_sha256"],
                         hashlib.sha256(self.installed.read_bytes()).hexdigest())
        verify = subprocess.run(installed_launcher_command(self.installed, self.home, "--verify-report",
                                                          str(report_path)),
                                env=self.python_environment(),
                                cwd=self.outside, capture_output=True, text=True, timeout=30)
        self.assertEqual(verify.returncode, 0, verify.stderr)
        with self.owner_home():
            self.assertTrue(sc.report_is_attested(report))
            self.assertIn("0/20 verified", sc.render_markdown(report))
            for field, value in (("attested", False), ("passed", 20), ("attestation", {})):
                changed = {**report, field: value}
                self.assertFalse(sc.report_is_attested(changed))
                text = sc.render_markdown(changed)
                self.assertTrue(text.startswith(self.launcher.UNATTESTED))
                self.assertNotIn("/20 verified", text)
            legacy = {k: v for k, v in report.items() if k != "attested"}
            self.assertFalse(sc.report_is_attested(legacy))
            receipt_path = self.launcher._receipt_path(report["attestation"]["nonce"])
            receipt = json.loads(receipt_path.read_bytes())
            receipt["attestation"]["tree_id"] = "0" * 40
            receipt_path.write_text(json.dumps(receipt))
            self.assertFalse(sc.report_is_attested(report))
        verify = subprocess.run(installed_launcher_command(self.installed, self.home, "--verify-report",
                                                          str(report_path)),
                                env=self.python_environment(),
                                cwd=self.outside, capture_output=True, text=True, timeout=30)
        self.assertEqual(verify.returncode, 2, verify.stderr)
        self.assertTrue(verify.stdout.startswith(self.launcher.UNATTESTED))
        script.write_bytes(original)
        cli = self.modules["director-scorecard"]
        # Candidate supplies all the old environment claims, a completed nonce, and a true descriptor digest for
        # the real owner account (not a forged one -- that boundary is tested separately below). It still cannot
        # replay or forge a nonce the launcher already sealed, or a syntactically invalid one, into attestation.
        env = {**self.python_environment(), cli.TREE_ENV: str(self.repo), cli.REPO_ENV: str(self.repo),
               cli.SHA_ENV: self.pin, cli.DESCRIPTOR_ENV: self.descriptor_digest(),
               self.launcher.NONCE_ENV: report["attestation"]["nonce"]}
        for nonce in ("", report["attestation"]["nonce"], "../invalid"):
            env[self.launcher.NONCE_ENV] = nonce
            direct = subprocess.run(evaluator_bootstrap_command(self.repo / "src", self.script, self.home,
                                                              *arguments),
                                    env=env, cwd=self.outside, capture_output=True, text=True, timeout=120)
            self.assertEqual(direct.returncode, 0, direct.stderr)
            self.assertTrue(direct.stdout.startswith(self.launcher.UNATTESTED))
            unattested = json.loads(report_path.read_bytes())
            self.assertIs(unattested["attested"], False)
            self.assertEqual(unattested["passed"], "UNATTESTED")
            self.assertFalse(unattested["all_checks_verified"])
            self.assertFalse(unattested["activation_authorized"])
            self.assertTrue(all(item["status"] == "UNKNOWN" for item in unattested["checks"]))
        # A forged owner-home claim, paired with a self-authored descriptor whose digest it supplies itself,
        # still cannot relocate the trust root: this process's real OS account never matches the attacker's
        # directory, so the whole run refuses before any repository module is imported (#287 item 34) -- not
        # merely because some other, unrelated variable happens to be missing.
        forged_home = self.outside / "forged-home"
        (forged_home / ".director-scorecard").mkdir(parents=True)
        forged_descriptor_path = forged_home / ".director-scorecard" / "release-descriptor.json"
        forged_descriptor_path.write_text(json.dumps({"version": cli.DESCRIPTOR_VERSION,
                                                      "evaluator_sha": self.pin}))
        forged_env = {**self.python_environment(),
                     cli.TREE_ENV: str(self.repo), cli.REPO_ENV: str(self.repo), cli.SHA_ENV: self.pin,
                     self.launcher.NONCE_ENV: report["attestation"]["nonce"],
                     cli.OWNER_HOME_ENV: str(forged_home),
                     cli.DESCRIPTOR_ENV: hashlib.sha256(forged_descriptor_path.read_bytes()).hexdigest()}
        forged = subprocess.run([sys.executable, str(self.script), *arguments], env=forged_env,
                               cwd=self.outside, capture_output=True, text=True, timeout=120)
        self.assertEqual(forged.returncode, 2, forged.stderr)
        self.assertIn("evaluator revision not pinned", forged.stderr)

    def test_score_attestation_and_containment_limitations(self):
        nonce = "a" * 64
        fields = {"nonce": nonce, "evaluator_sha": self.pin, "tree_id": "b" * 40,
                  "descriptor_sha256": self.descriptor_digest(),
                  "launcher_sha256": hashlib.sha256(self.installed.read_bytes()).hexdigest()}
        with self.owner_home(), patch.dict(os.environ, {
                self.launcher.NONCE_ENV: nonce, self.launcher.SHA_ENV: self.pin,
                self.launcher.DESCRIPTOR_ENV: self.descriptor_digest()}):
            receipt_path = self.launcher._receipt_path(nonce)
            receipt_path.parent.mkdir()
            receipt = {"attestation": fields, "tree": str(sc._REPO_ROOT), "report_sha256": None}
            receipt_path.write_text(json.dumps(receipt))
            report = sc.score(SHA, runtime_observations(evaluate_rules=True), now=NOW)
            self.assertIs(report["attested"], True)
            self.assertEqual(report["passed"], 1)
            self.assertEqual(report["percent"], 5)
            self.assertFalse(sc.report_is_attested(report))  # not finalized by launcher
            limitations = " ".join(report["limitations"])
            self.assertIn(", ".join(sorted(sc._CONTAINED_RUNTIME + sc._CONTAINED_CAPTURES + sc._CONTAINED_CANDIDATE)),
                          limitations)
            self.assertIn("#313 / PR #327", limitations)
            for digest in ("", "0" * 64):
                with self.subTest(descriptor_digest=digest), patch.dict(os.environ, {
                        self.launcher.DESCRIPTOR_ENV: digest}):
                    self.assertIsNone(self.launcher.run_attestation(sc._REPO_ROOT))
                    self.assertIsNone(pse.cli_release_descriptor())
            for key in ("evaluator_sha", "launcher_sha256", "descriptor_sha256", "nonce", "tree_id"):
                with self.subTest(field=key):
                    changed = {**receipt, "attestation": {**fields, key: "tampered"}}
                    receipt_path.write_text(json.dumps(changed))
                    report = sc.score(SHA, runtime_observations(evaluate_rules=True), now=NOW)
                    self.assertIs(report["attested"], False)
                    self.assertEqual(report["passed"], "UNATTESTED")
                    self.assertTrue(sc.render_markdown(report).startswith(self.launcher.UNATTESTED))

    def test_forged_pending_receipt_cannot_relocate_the_OS_owner_root(self):
        fake = self.outside / "forged-owner"
        root = fake / ".director-scorecard"
        (root / "attestations").mkdir(parents=True)
        (root / "launcher.py").write_bytes(self.installed.read_bytes())
        (root / "release-descriptor.json").write_bytes(self.descriptor.read_bytes())
        nonce = "a" * 64
        fields = {"nonce": nonce, "evaluator_sha": self.pin, "tree_id": "b" * 40,
                  "descriptor_sha256": self.descriptor_digest(),
                  "launcher_sha256": hashlib.sha256(self.installed.read_bytes()).hexdigest()}
        (root / "attestations" / (nonce + ".json")).write_text(json.dumps({
            "attestation": fields, "tree": str(sc._REPO_ROOT), "report_sha256": None}))
        cli = self.modules["director-scorecard"]
        with self.owner_home(), patch.object(cli, "account_home", return_value=self.home), patch.dict(os.environ, {
                "HOME": str(fake), "USERPROFILE": str(fake), self.launcher.OWNER_HOME_ENV: str(fake),
                self.launcher.DESCRIPTOR_ENV: self.descriptor_digest(), self.launcher.NONCE_ENV: nonce,
                self.launcher.SHA_ENV: self.pin, self.launcher.TREE_ENV: str(sc._REPO_ROOT),
                self.launcher.REPO_ENV: str(self.repo)}):
            self.assertIsNone(self.launcher.run_attestation(sc._REPO_ROOT))
            self.assertIsNone(pse.cli_release_descriptor())
            self.assertIsNone(cli.pinned_evaluator())

    def test_non_evaluator_descriptor_rotation_prevents_sealing(self):
        self.script.write_text(self.script.read_text() +
            "descriptor = receipt.parent.parent / 'release-descriptor.json'\n"
            "changed = json.loads(descriptor.read_bytes())\n"
            "changed['security_base_sha'] = '1' * 40\n"
            "descriptor.write_text(json.dumps(changed))\n")
        self.git("add", ".")
        self.git("commit", "-qm", "rotate other descriptor field during collection")
        self.pin = self.git("rev-parse", "HEAD").decode().strip()
        self.git("update-ref", "refs/remotes/github/main", self.pin)
        self.descriptor.write_text(json.dumps({"version": self.launcher.DESCRIPTOR_VERSION,
                                              "evaluator_sha": self.pin}))
        result = self.run_launcher()
        self.assertEqual(result.returncode, 2, result.stderr)
        self.assertIn(self.launcher.UNATTESTED, result.stderr)
        self.assertEqual(json.loads(self.descriptor.read_bytes())["evaluator_sha"], self.pin)
        receipts = list((self.home / ".director-scorecard" / "attestations").glob("*.json"))
        self.assertEqual(len(receipts), 1)
        self.assertEqual(json.loads(receipts[0].read_bytes())["report_sha256"], "INVALID")

    def test_every_git_transport_disables_replacements_and_uses_minimal_environment(self):
        # Do not let mocks at _run_bytes conceal a missing subprocess-level defense.
        class Captured(Exception):
            pass

        def capture(arguments, **options):
            self.assertEqual(arguments[:2], ["git", "--no-replace-objects"])
            env = options["env"]
            self.assertEqual(env["GIT_NO_REPLACE_OBJECTS"], "1")
            self.assertEqual(env["GIT_GRAFT_FILE"], os.devnull)
            self.assertEqual(env["GIT_CONFIG_GLOBAL"], os.devnull)
            self.assertEqual(env["GIT_CONFIG_NOSYSTEM"], "1")
            self.assertFalse({key.upper() for key in env} - {
                "PATH", "SYSTEMROOT", "WINDIR", "TEMP", "TMP", "TMPDIR", "GIT_NO_REPLACE_OBJECTS",
                "GIT_GRAFT_FILE", "GIT_CONFIG_GLOBAL", "GIT_CONFIG_NOSYSTEM"})
            raise Captured

        for module in self.modules.values():
            with patch.object(module.subprocess, "run", side_effect=capture), self.assertRaises(Captured):
                module._git(self.repo, "rev-parse", self.pin)
        with patch.object(sc, "launch_contained_process", side_effect=capture), self.assertRaises(Captured):
            sc._run_bytes(["git", "-C", str(self.repo), "show", self.pin])


class TrustedCollectionLaneTests(unittest.TestCase):
    """Real store collection; missing paid/approval evidence must stay UNKNOWN."""

    def setUp(self):
        self.dsn = os.environ.get("LANGGRAPH_RUNTIME_POSTGRES_TEST_DSN", "").strip()
        if not self.dsn:
            self.skipTest("LANGGRAPH_RUNTIME_POSTGRES_TEST_DSN unset; sanctioned Postgres lane unavailable")
        import psycopg
        from tests import test_primary_scorecard_evidence as fixtures
        try:
            with psycopg.connect(self.dsn, connect_timeout=3):
                pass
        except psycopg.OperationalError:
            self.skipTest("Sanctioned Postgres lane unavailable; connection details withheld")
        self.fixtures = fixtures
        self.primary = fixtures.ScorecardEvidencePostgresTests()
        self.primary.coordinator_fixtures = fixtures._load("test_primary_coordinator")
        self.primary.setUp()
        self.addCleanup(self.primary.tearDown)

    def clock_bounds(self):
        """Bound fixture evidence from both host and disposable database clocks."""
        before = datetime.now(timezone.utc)
        with self.primary.handle.pool.connection() as connection:
            database_now = connection.execute("SELECT clock_timestamp() AS observed").fetchone()["observed"]
        after = datetime.now(timezone.utc)
        return min(before, database_now), max(after, database_now)

    def produce_offline_trials(self):
        """Use the production graph, approval, checkpoint and offline ledger wiring."""
        from tests import test_primary_default as fixture

        settings = dataclasses.replace(fixture.Settings(), allow_paid_runs=False,
            langgraph_primary_offline_simulation_enabled=True,
            project_allowlist=("default",), repository_allowlist=("owner/director-orchestrator",),
            allowed_starting_refs=("main",))
        services = fixture.DefaultOfflineSimulationServices(settings, packet_router=fixture.packet_router(settings))

        def coordinator():
            value = fixture.PrimaryTaskCoordinator(self.primary.handle, services.handlers(),
                owner_token=self.fixtures.TEST_OWNER_TOKEN, checkpoint_namespace="default-director-primary-v1",
                auto_execute_provider=False, application_projection_provider=services.application_projection)
            value.adopt_or_activate_new_intake()
            return value

        current = coordinator()
        application = fixture.DefaultPrimaryApplication(settings, current, services,
            fixture.DefaultPrimaryAuthority(starting_sha=SHA, authority_snapshot_digest=fixture.digest("authority")),
            parallel_dispatcher=fixture.build_offline_parallel_dispatcher(services, lambda: current))
        tasks = []
        # Network and native process boundaries are fatal here; only offline doubles may execute.
        with patch("httpx.AsyncClient.send", side_effect=AssertionError("offline network call")) as network, \
                patch("subprocess.Popen", side_effect=AssertionError("offline native call")) as process:
            for index in range(10):
                intake = fixture.DefaultPrimaryApplicationIntegrationTests.intake().model_copy(update={
                    "source_event_id": f"trusted-offline-{index}",
                    "thread_ts": f"{int(time.time())}.{index:06d}"})
                pending = application.create_intake(intake,
                    intake_authentication=fixture.IntakeAuthentication.BEARER_DRY_RUN)
                before = current.get_projection(pending.task_id)
                if index == 0:
                    # Reconstruct the coordinator and recover the durable approval interrupt.
                    current = coordinator()
                    recovered = current.recover(pending.task_id)
                    self.assertEqual(recovered.projection_digest, before.projection_digest)
                    application.coordinator = current
                approval = before.projection["pending_approval"]
                command_id = f"trusted-approve-{index}"
                completed = application.resume_approval(fixture.ApprovalResume(
                    task_id=pending.task_id, kind=fixture.ApprovalKind(approval["kind"]),
                    request_digest=approval["request_digest"], approval_event_id=command_id,
                    decision=fixture.ApprovalDecision.APPROVE))
                self.assertEqual(completed.status, fixture.TaskStatus.DONE)
                current.record_command_receipt(task_id=pending.task_id, operation="approval_resume",
                    command_id=command_id, command_digest=fixture.digest(command_id),
                    projection=current.get_projection(pending.task_id))
                tasks.append(pending.task_id)
            network.assert_not_called()
            process.assert_not_called()
        self.primary.coordinator = current
        self.assertGreater(services.provider_calls, 0)  # Offline doubles actually ran.
        return tasks

    def produce_metered_attempt(self):
        """Receive a native response through the real transport, meter and attempt ledger."""
        from types import SimpleNamespace
        from tests import test_response_meter as fixture
        from director_orchestrator.antigravity_team import PrimaryProviderBudgetAuthority
        from director_orchestrator.antigravity_team_routing import PrimaryProviderBudgetRouting, live_provider_admissions
        from director_orchestrator.primary_parallel import ParallelAssignment, ParallelDispatchPolicy, ParallelAssignmentStatus
        from director_orchestrator.primary_coordinator import PrimaryTaskCoordinator
        from director_orchestrator.packet_contracts import canonical_json_bytes

        meter_fixture = fixture.ResponseMeterTests()
        meter_fixture.setUpClass()
        self.addCleanup(meter_fixture.tearDownClass)
        meter_fixture.setUp()
        self.addCleanup(meter_fixture.tearDown)
        authority = PrimaryProviderBudgetAuthority(meter_fixture.store, primary_schema=self.primary.schema)
        routing = PrimaryProviderBudgetRouting(authority=authority, pool=self.primary.handle.pool)
        coordinator = PrimaryTaskCoordinator(self.primary.handle, self.primary.coordinator_fixtures.handlers(),
            owner_token=self.fixtures.TEST_OWNER_TOKEN, checkpoint_namespace="default-director-primary-v1",
            auto_execute_provider=False)
        coordinator.adopt_or_activate_new_intake()
        task = "DIR-LG-FEED"
        coordinator.create_intake(self.primary.coordinator_fixtures.request(task))
        policy = ParallelDispatchPolicy()
        plan = coordinator.register_parallel_plan(task_id=task,
            plan_digest="sha256:" + "7" * 64,
            assignments=(ParallelAssignment("metered", 1, "openai", "fixture"),), policy=policy)
        reservation, = coordinator.reserve_parallel_ready(task_id=task, policy=policy)
        budget = fixture.team.signed(meter_fixture.budget.model_copy(update={"task_id": task}),
                                     fixture.team.fixtures.OWNER_SECRET)
        with self.primary.handle.pool.connection() as connection, connection.transaction():
            authority.register(connection, budget)
        packet = json.loads(meter_fixture.packet)
        packet.update(task_id=task, assignment_id=reservation.assignment_id, starting_ref=SHA)
        admission = live_provider_admissions(settings=fixture.Settings(), budget_routing=routing,
            team_routing=None, provider="openai", packet=packet, attempt_usd=0.00006)
        attempt = coordinator.reserve_provider_attempt(reservation=reservation, attempt_ordinal=1,
            format_roster=(("model-work-packet-v1", "responses-api"),),
            idempotency_key_digest="sha256:" + "6" * 64, budget_evidence_digest="sha256:" + "5" * 64,
            **admission)
        packet_bytes = canonical_json_bytes(packet)
        packet_digest = "sha256:" + hashlib.sha256(packet_bytes).hexdigest()
        enrollment = fixture.team.signed(meter_fixture.enrollment.model_copy(update={
            "task_id": task, "assignment_id": reservation.assignment_id,
            "attempt_digest": attempt.attempt_digest, "work_packet_digest": packet_digest}),
            fixture.team.fixtures.OWNER_SECRET)
        meter = fixture.EnrolledResponseMeter(enrollment=enrollment, authority=authority,
                                              pool=meter_fixture.store._pool)
        context = SimpleNamespace(task_id=task, assignment_id=reservation.assignment_id,
            idempotency_key=attempt.attempt_digest, work_packet_digest=packet_digest,
            fencing_generation=coordinator.get_task_writer(task).fencing_generation,
            timeout_seconds=5, total_token_limit=1000)
        requests = []

        def respond(request):
            requests.append(request.url.path)
            body = ({"object": "response.input_tokens", "input_tokens": 8}
                    if request.url.path.endswith("input_tokens") else meter_fixture.native())
            return httpx.Response(200, json=body, headers=meter_fixture.headers)

        original = httpx.AsyncClient
        with patch("director_orchestrator.primary_transports.httpx.AsyncClient",
                side_effect=lambda **kwargs: original(transport=httpx.MockTransport(respond), **kwargs)):
            result = fixture.OpenAIResponsesPacketTransport(api_key="test-key", model=enrollment.model,
                response_meter=meter).send(packet_bytes, context=context)
        self.assertEqual(len(requests), 2)  # Input count plus one response; no retry.
        result_digest = "sha256:" + hashlib.sha256(canonical_json_bytes(result)).hexdigest()
        coordinator.record_provider_attempt(attempt=attempt, status=ParallelAssignmentStatus.SUCCEEDED,
            result_digest=result_digest, reason_code="attempt_succeeded")
        coordinator.record_parallel_result(plan_digest=plan, reservation=reservation,
            status=ParallelAssignmentStatus.SUCCEEDED, result_digest=result_digest, reason_code="attempt_succeeded")
        self.primary.coordinator = coordinator
        return task, fixture.team.fixtures.ROUTE_SECRET, fixture.team.fixtures.OWNER_SECRET

    def test_tls_owner_bound_collection_reads_producers_and_rejects_hostile_candidate(self):
        from pathlib import PurePosixPath
        from director_orchestrator.config import Settings
        from director_orchestrator import primary_activation_evidence as acceptance
        from director_orchestrator import primary_generation as generation_module
        from director_orchestrator.provider_activation import (
            ProviderActivationRegistry, ProviderActivationStage, ProviderActivationSurface,
        )
        from director_orchestrator.provider_validation import (
            PostgresValidationStore, ValidationBridgeService, ValidationRequest, production_configuration_digest,
        )
        from director_orchestrator.host_provider_bridge import WindowsHostProviderExecutor
        from director_orchestrator.host_provider_bridge_server import executable_digest
        from psycopg.conninfo import conninfo_to_dict

        ca = os.environ.get("LANGGRAPH_RUNTIME_POSTGRES_TEST_CA")
        if not ca or conninfo_to_dict(self.dsn).get("sslmode") != "verify-full":
            self.skipTest("Verified TLS lane required: -Action Test -Tls")
        fixture = self.fixtures._load("test_provider_validation")
        world = World(self)
        world.consistency = world.captures = None
        # The fixtures below mint test authority locally; no ambient authority,
        # candidate reports, provider calls, or external writes are used.
        adoption_fixture_class = self.fixtures._load("test_local_activation_evidence").LocalActivationEvidenceTests
        local = adoption_fixture_class()
        local.setUp()
        self.addCleanup(local.doCleanups)
        self.addCleanup(local.tearDown)
        root = Path(local.temporary.name)
        local.adoption_document.update(repository=sc.REPOSITORY, reviewed_source_commit=SHA,
                                       reviewed_source_tree=world.commit_tree)
        adoption_path, adoption_pin = local.write_adoption(owner_token=self.fixtures.TEST_OWNER_TOKEN)
        provider_binding = dataclasses.replace(fixture.binding(), binding_version=root.name)
        raw_bindings = json.dumps({"claude": {key: value for key, value in dataclasses.asdict(provider_binding).items()
                                             if key != "provider_id"}})
        identity = acceptance.ActivationIdentity(SHA, world.commit_tree, "local", DEPLOYMENT,
            self.primary.identity.database_identity, self.primary.identity.database_instance_id,
            self.primary.schema, "default-director-primary-v1")
        settings = dataclasses.replace(Settings(), app_env="local",
            repository_allowlist=(sc.REPOSITORY,), langgraph_primary_service_repository=sc.REPOSITORY,
            langgraph_primary_postgres_dsn=self.dsn, langgraph_primary_postgres_schema=self.primary.schema,
            langgraph_primary_checkpoint_namespace=identity.checkpoint_namespace,
            langgraph_primary_pinned_commit_sha=SHA, langgraph_primary_pinned_tree_sha=world.commit_tree,
            langgraph_primary_acceptance_mode="owner-local-evidence-v1",
            langgraph_primary_owner_token=self.fixtures.TEST_OWNER_TOKEN,
            langgraph_primary_local_evidence_adoption_path="/data/adoption.json",
            langgraph_primary_local_evidence_adoption_sha256=adoption_pin,
            langgraph_primary_acceptance_journal_path="/data/selected.sqlite3",
            langgraph_primary_provider_activation_bindings_json=raw_bindings,
            langgraph_primary_required_providers=("claude",))
        manifest = dict(version="director-primary-generation/owner-local-evidence-v1",
            activation=dataclasses.asdict(identity), journal_path=settings.langgraph_primary_acceptance_journal_path,
            owner_adoption_path=settings.langgraph_primary_local_evidence_adoption_path,
            owner_adoption_sha256=adoption_pin, provider_bindings_sha256=hashlib.sha256(raw_bindings.encode()).hexdigest(),
            deployment_configuration_sha256=generation_module.deployment_digest(settings),
            image_id=IMAGE, resolved_compose_sha256="9" * 64)
        manifest_path = root / "manifest.json"
        manifest_path.write_text(json.dumps(manifest), encoding="utf-8")
        pin = hashlib.sha256(manifest_path.read_bytes()).hexdigest()
        environment = {"DIRECTOR_RUNTIME_IMAGE_ID": IMAGE, "DIRECTOR_RESOLVED_DEPLOYMENT_SHA256": "9" * 64,
            "LANGGRAPH_PRIMARY_GENERATION_MANIFEST_PATH": "/data/manifest.json",
            "LANGGRAPH_PRIMARY_GENERATION_MANIFEST_SHA256": pin,
            "LANGGRAPH_PRIMARY_PROVIDER_ACTIVATION_BINDINGS_JSON": raw_bindings}
        # The real reservation producer sees its Linux /data mount on Windows.
        # Only filesystem paths are mapped; all generation/signature checks and
        # journal writes execute unchanged, before the read-only collection.
        def mounted(path):
            return root.joinpath(*PurePosixPath(path).relative_to("/data").parts)

        class MountedPath(PurePosixPath):
            def read_bytes(self):
                return mounted(self).read_bytes()

        real_open, real_connect = os.open, sqlite3.connect

        def mapped_open(path, *args, **kwargs):
            return real_open(mounted(path) if str(path).startswith("/data/") else path, *args, **kwargs)

        with patch.object(generation_module, "Path", MountedPath), \
                patch.object(generation_module, "GENERATION_DATA_ROOT", MountedPath("/data")), \
                patch.object(acceptance, "Path", side_effect=mounted), \
                patch.object(os, "open", side_effect=mapped_open), \
                patch.object(sqlite3, "connect", side_effect=lambda path: real_connect(mounted(path))):
            generation_module.require_generation(settings, identity, reserve=True, environment=environment)
        environment.update(LANGGRAPH_PRIMARY_GENERATION_MANIFEST_PATH="/data/manifest.json",
            LANGGRAPH_PRIMARY_GENERATION_MANIFEST_SHA256=pin,
            LANGGRAPH_PRIMARY_POSTGRES_DSN=self.dsn, DIRECTOR_PROVIDER_VALIDATION_POSTGRES_DSN=self.dsn,
            DIRECTOR_PROVIDER_VALIDATION_CANDIDATE=SHA, DIRECTOR_PROVIDER_VALIDATION_TREE=world.commit_tree)
        # A real admission, execution claim, signed V2 capture, and settlement.
        validation = PostgresValidationStore(self.dsn)
        validation.bootstrap()
        work = fixture.work_packet()
        work["starting_ref"] = SHA
        native = json.loads(fixture.claude_cli_native())
        native_path = root / "native_fixture.py"
        native_path.write_text("import sys\nsys.stdin.buffer.read()\nprint(" + repr(json.dumps(native)) + ")\n",
                               encoding="utf-8")
        account = root / "fixture-account-pin"
        account.write_text("Synthetic account binding; no credential", encoding="utf-8")
        executor = WindowsHostProviderExecutor(
            {"claude": (str(Path(sys.executable).resolve()), str(native_path))}, cwd=root)
        configuration = production_configuration_digest(executor, "claude", account_files=(str(account),))
        executable = executable_digest(executor.commands["claude"])
        expires = int(self.clock_bounds()[1].timestamp()) + 3600
        validation.create_generation(generation=pin, candidate=SHA, tree=world.commit_tree,
            owner_token=fixture.OWNER, expires_at=expires, budget_units=2,
            lanes={"claude": {"binding": dataclasses.asdict(provider_binding), "configuration_digest": configuration,
                              "cost_units": 2, "work_packet": work}})
        bridge = ValidationBridgeService(store=validation, production_executor=executor,
            capture_key=fixture.KEY, owner_token=fixture.OWNER, account_files={"claude": (str(account),)})
        receipt = bridge.run(ValidationRequest(generation=pin, provider="claude"), fixture.OWNER)
        evidence_digest = receipt["evidence_digest"]
        observed = self.clock_bounds()[0] - timedelta(minutes=1)
        registry = ProviderActivationRegistry(self.primary.handle.claim_store, provider_binding)
        for surface in ProviderActivationSurface:
            for index, stage in enumerate(ProviderActivationStage):
                when = observed + timedelta(seconds=index)
                registry.record(surface=surface, stage=stage, evidence_id=f"tls-{surface.value}-{index}",
                    evidence_digest=evidence_digest, observed_at=when,
                    expires_at=datetime.fromtimestamp(expires, timezone.utc), now=when)
        self.primary.coordinator.activate_new_intake(expected_generation=0)
        started = self.clock_bounds()[0]
        payload = health()
        payload["langgraph_primary"]["intake_fencing_generation"] = 1
        runtime = runtime_fixture(env=environment, runtime_tree=world.commit_tree, health=payload,
            collected_at=started, collection_end=lambda: self.clock_bounds()[1])
        world.rows[0]["Config"]["Env"] = [f"{key}={value}" for key, value in environment.items()]
        world.rows[0]["Mounts"] = [{"Type": "bind", "Source": str(root), "Destination": "/data"}]
        inputs = {"environment": environment, "settings": dataclasses.asdict(settings),
            "mounts": [{"source": str(root), "destination": "/data"}],
            "ca": {"path": str(Path(ca).resolve()), "sha256": hashlib.sha256(Path(ca).read_bytes()).hexdigest()},
            "capture_key": fixture.KEY, "route_verifier_secret": "test-route-authority-only",
            "owner_authority_secret": "test-owner-authority-only"}
        descriptor = {"version": self.fixtures.evidence.CLI_RELEASE_DESCRIPTOR_VERSION,
            "trusted_collection_inputs_env": "TEST_SCORECARD_INPUTS",
            "releases": [{"provider": "claude", "product": "anthropic-claude", "executable_sha256": executable}]}
        candidate_reads = []
        original_run = world.run

        def hostile_run(args, timeout=15):
            if args[:2] == ["docker", "exec"] and "director_orchestrator.primary_generation" in args:
                candidate_reads.append(True)
                return json.dumps({"checks": [{"id": key, "status": "PASS"}
                    for key in ("06", "07", "08", "10", "11", "12", "15", "17", "20")]}).encode()
            return original_run(args, timeout)

        with patch.object(sc, "cli_release_descriptor", return_value=descriptor), \
                patch.dict(os.environ, {"TEST_SCORECARD_INPUTS": json.dumps(inputs)}), \
                patch.object(sc, "_run_bytes", side_effect=hostile_run):
            consistency, captures = sc._trusted_collection(runtime, [])
            self.assertIsNotNone(captures)
            self.assertEqual(captures["lanes"]["claude"]["product"], "anthropic-claude")
            for surface in captures["lanes"]["claude"]["surfaces"].values():
                self.assertEqual(surface["executable_sha256"], executable)
            # 05 reads the real intake-authority row in the same snapshot; the lease token never leaves the evaluator.
            authority = consistency["intake_authority"]
            self.assertEqual(set(authority), {"intake_owner", "legacy_new_intake_disabled", "fencing_generation",
                                              "lease_live", "owner_token_matches", "lease_expires_at"})
            self.assertNotIn("owner_token\"", json.dumps(consistency, default=str))
            self.assertIs(sc._intake_authority_observation(started, runtime, consistency).passed, True)
            # A token mismatch is a real FAIL, not a silent PASS: the evaluator's own compare must matter.
            mismatched = {**consistency,
                         "intake_authority": {**consistency["intake_authority"], "owner_token_matches": False}}
            self.assertIs(sc._intake_authority_observation(started, runtime, mismatched).passed, False)
            observations = [sc._reconciliation_observation(started, runtime, consistency),
                            sc._acceptance_observation(started, SHA, consistency),
                            *sc._capture_observations(started, runtime, captures, None),
                            sc._monetary_observation(started, runtime, None, consistency, None),
                            sc._paid_observation(started, runtime, None, None, consistency, "fixture"),
                            sc._trial_observation(started, runtime, None, None, None)]
            report = sc.score(SHA, observations, now=started, runtime_sha=SHA, image_id=IMAGE)
            for check in ("07", "12", "17"):
                self.assertEqual(row(report, check)["status"], "PASS", check)
            for check in ("06", "08", "10", "11", "15", "20"):
                self.assertEqual(row(report, check)["status"], "UNKNOWN", check)

            offline_tasks = self.produce_offline_trials()
            from types import SimpleNamespace
            from director_orchestrator.primary_slack_delivery import PrimarySlackDelivery
            delivery = PrimarySlackDelivery(
                SimpleNamespace(handle=self.primary.handle, coordinator=self.primary.coordinator),
                dataclasses.replace(settings, slack_bot_token="offline-fixture-no-network",
                                    slack_channel_id="CDEFAULT", slack_owner_user_id="UOWNER"))
            self.assertGreater(delivery.enqueue(), 0)  # Real local ledger producer; no Slack transport.
            offline, _ = sc._trusted_collection(runtime, offline_tasks)
            snapshots, _ = sc._trusted_collection(runtime, offline_tasks, qualification_only=True)
            self.assertEqual(offline["counts"]["graph_task_count"], 10)
            self.assertEqual(offline["counts"]["provider_usage_invalid"], 0)
            for task in offline_tasks:
                entry = offline["tasks"][task]
                self.assertEqual(entry["application"]["execution_mode"], "offline_simulation")
                self.assertIsNone(entry["registered_plan"]["error"])
                self.assertTrue(entry["application"]["task_record"]["assignment_outcomes"])
                qualification = snapshots[task]
                self.assertTrue(qualification["complete"])
                self.assertTrue(qualification["snapshot"]["read_only"])
                self.assertTrue(qualification["snapshot"]["single_transaction"])
                self.assertEqual(qualification["projection"].task_id, task)
                self.assertEqual(entry["spend"], [])
                self.assertEqual(len(entry["approval_receipts"]), 1)
                # Local approval_resume is real, but has no authenticated gateway command.
                self.assertFalse(entry["approval_receipts"][0]["authorized"])

            from director_orchestrator.langgraph_postgres import read_postgres_slack_thread_binding
            intake = snapshots[offline_tasks[0]]["projection"].projection["application"]["task_record"]["intake"]
            expected = tuple(task for task in offline_tasks
                if snapshots[task]["projection"].projection["application"]["task_record"]["intake"]["thread_ts"]
                == intake["thread_ts"])
            matches = read_postgres_slack_thread_binding(self.dsn,
                channel_id=intake["channel_id"], thread_ts=intake["thread_ts"], schema=self.primary.schema,
                accepted_storage_identity=self.primary.identity.database_identity,
                accepted_instance_id=self.primary.identity.database_instance_id)
            self.assertEqual(set(matches), set(expected[:2]))

            # Exercise the actual consumer against those same TLS-backed producers.
            # Slack authentication is outside this task/readback-focused fixture;
            # any attempt to use a Director HTTP client here is fatal.
            reader = object.__new__(sc._SlackThreads)
            reader.runtime, reader._task_snapshots = runtime, {}
            reader.reads = Mock()
            reader.reads.get.side_effect = AssertionError("candidate HTTP forbidden")
            body, headers = reader.task(offline_tasks[0])
            self.assertEqual(body["task_id"], offline_tasks[0])
            self.assertEqual(headers["x-task-engine-owner"], "langgraph")
            deliveries = reader.deliveries(offline_tasks[0])
            self.assertTrue(deliveries)
            self.assertTrue(all(item["task_id"] == offline_tasks[0] for item in deliveries))
            self.assertEqual([item["client_msg_id"] for item in deliveries],
                             [item["client_msg_id"] for item in body["qualification_evidence"]["slack_deliveries"]])
            reader.reads.get.assert_not_called()

            paid_task, route_secret, owner_secret = self.produce_metered_attempt()
            inputs.update(route_verifier_secret=route_secret.decode(), owner_authority_secret=owner_secret.decode())
            with patch.dict(os.environ, {"TEST_SCORECARD_INPUTS": json.dumps(inputs)}):
                settled, _ = sc._trusted_collection(runtime, [paid_task])
                entry = settled["tasks"][paid_task]
                self.assertEqual(len(entry["spend"]), 1)
                self.assertTrue(entry["spend"][0]["usage_verified"])
                self.assertTrue(entry["spend"][0]["request_correlated"])
                self.assertEqual(entry["spend"][0]["actual_microusd"], 58)
                self.assertTrue(entry["budgets"][0]["signature_verified"])
                # The live collection path must retain UNKNOWN without Slack evidence,
                # even though real approval, restart, offline and metered rows now exist.
                with patch.object(sc, "_runtime", return_value=([], runtime)), \
                        patch.object(sc, "_deployment_state", return_value=()):
                    held = sc._Held()
                    collected, _ = sc._deployment_observations(started, SHA, DEPLOYMENT,
                        channel=None, gateway=None, topology=False, drills={}, approval_task=offline_tasks[0],
                        trials=None, rubric_path=None, paid_thread=None, paid_rubric_path=None, held=held)
                by_check = {item.check_id: item for item in collected}
                for check in ("06", "08", "10", "11", "15", "20"):
                    self.assertIsNone(by_check[check].passed, check)
                self.assertIsNone(by_check["12"].passed)
                self.assertIsNone(by_check["17"].passed)
                # 05's underlying intake-authority read genuinely passes here (real coordinator, matching
                # owner token, live lease) — but it stays contained pending the A3 reviewed-image admission
                # gate, so the live collection path must still report it as UNKNOWN, never PASS.
                self.assertIsNone(by_check["05"].passed)
                # The admission gate is handed the real graded original, not the containment placeholder, and the
                # running identity it compares with the owner's pin (no gateway was named, so it is not bound).
                self.assertIs(held.observations["05"].passed, True)
                self.assertEqual(held.identity["director_image_id"], runtime.image_id)
                self.assertIs(held.identity["gateway_bound"], False)
            self.primary.coordinator.create_intake(self.primary.coordinator_fixtures.request("DIR-LG-FADE"))
            hostile, _ = sc._trusted_collection(runtime, ["DIR-LG-FADE"])
            verdict = sc._reconciliation_observation(started, runtime, hostile)
            self.assertIsNot(verdict.passed, True)
        self.assertFalse(candidate_reads, "Candidate reports cannot replace trusted evidence")

    def test_lane_transport_blocks_all_nine_checks_even_with_hostile_candidate_pass(self):
        from director_orchestrator.config import Settings
        from psycopg.conninfo import conninfo_to_dict

        if conninfo_to_dict(self.dsn).get("sslmode") != "disable":
            self.skipTest("Non-TLS refusal regression; run the lane without -Tls")
        world = World(self)
        # Do not feed World's hand-authored evaluator evidence into collection.
        world.consistency = world.captures = None
        environment = sc._environment(world.rows[0])
        environment.update(LANGGRAPH_PRIMARY_POSTGRES_DSN=self.dsn,
            DIRECTOR_PROVIDER_VALIDATION_POSTGRES_DSN=self.dsn,
            DIRECTOR_PROVIDER_VALIDATION_CANDIDATE=SHA,
            DIRECTOR_PROVIDER_VALIDATION_TREE=world.commit_tree,
            DIRECTOR_RUNTIME_IMAGE_ID=IMAGE)
        settings = dataclasses.replace(Settings(), langgraph_primary_postgres_dsn=self.dsn,
            langgraph_primary_postgres_schema=self.primary.schema,
            langgraph_primary_pinned_commit_sha=SHA, langgraph_primary_pinned_tree_sha=world.commit_tree)
        world.rows[0]["Config"]["Env"] = [f"{key}={value}" for key, value in environment.items()]
        world.rows[0]["Mounts"] = []
        inputs = {"environment": environment, "settings": dataclasses.asdict(settings), "mounts": []}
        runtime = runtime_fixture(env=environment, runtime_tree=world.commit_tree)
        original_run = world.run
        candidate_reads = []

        def hostile_run(args, timeout=15):
            if args[:2] == ["docker", "exec"] and "director_orchestrator.primary_generation" in args:
                candidate_reads.append(True)
                return json.dumps({"checks": [{"id": key, "status": "PASS"}
                    for key in ("06", "07", "08", "10", "11", "12", "15", "17", "20")]}).encode()
            return original_run(args, timeout)

        self.primary.coordinator.activate_new_intake(expected_generation=0)
        for hostile in (False, True):
            with self.subTest(hostile=hostile):
                if hostile:
                    # The producer creates actual in-flight work, not a fabricated report/count.
                    request = self.primary.coordinator_fixtures.request("DIR-LG-FADE")
                    self.primary.coordinator.create_intake(request)
                    world.run = hostile_run
                store_report = self.primary.report()
                self.assertEqual(store_report["counts"]["graph_task_count"], int(hostile))
                self.assertEqual(store_report["counts"]["nonterminal_projections"], int(hostile))
                with patch.object(sc, "cli_release_descriptor", return_value={
                        "trusted_collection_inputs_env": "TEST_SCORECARD_INPUTS"}), \
                        patch.dict(os.environ, {"TEST_SCORECARD_INPUTS": json.dumps(inputs)}), \
                        patch("director_orchestrator.langgraph_postgres.database_binding") as binding_read:
                    # All prior owner/inspect bindings match. Reach the DSN parser, but the TLS
                    # requirement refuses before database_binding or any trusted store read.
                    with patch.object(sc, "_run_bytes", side_effect=world.run), \
                            patch("psycopg.conninfo.conninfo_to_dict", wraps=conninfo_to_dict) as parsed:
                        with self.assertRaisesRegex(ValueError, "^Trusted collection unavailable:"):
                            sc._trusted_collection(runtime, [])
                        self.assertEqual(parsed.call_count, 1)
                    report = world.report()
                    self.assertFalse(binding_read.called, "TLS refusal must precede database binding")
                for key in ("06", "07", "08", "10", "11", "12", "15", "17", "20"):
                    self.assertEqual(row(report, key)["status"], "UNKNOWN", key)
                    self.assertEqual(row(report, key)["explanation"], "collector not yet trusted", key)
        self.assertFalse(candidate_reads, "Candidate in-image report must never be executed")

    def test_real_signed_cli_capture_remains_unattested_with_pinned_release(self):
        self.check_signed_cli_capture(None, "anthropic-claude-unattested")

    def test_real_signed_cli_capture_attests_only_the_pinned_executable(self):
        for executable, product in (("e" * 64, "anthropic-claude"),
                                    ("f" * 64, "anthropic-claude-digest-mismatch")):
            with self.subTest(product=product):
                self.check_signed_cli_capture(executable, product)

    def check_signed_cli_capture(self, executable, product):
        from types import SimpleNamespace
        from director_orchestrator.packet_contracts import canonical_json_bytes
        from director_orchestrator.provider_activation import (
            ProviderActivationRegistry, ProviderActivationStage, ProviderActivationSurface,
        )
        from director_orchestrator.provider_validation import (
            CaptureVerifier, PostgresValidationStore, ValidationRequest, make_capture,
        )

        fixture = self.fixtures._load("test_provider_validation")
        store = PostgresValidationStore(self.dsn)
        store.bootstrap()
        generation = hashlib.sha256(os.urandom(32)).hexdigest()
        expires = int(self.clock_bounds()[1].timestamp()) + 3600
        provider_binding = dataclasses.replace(fixture.binding(), binding_version=generation)
        store.create_generation(generation=generation, candidate=fixture.CANDIDATE, tree=fixture.TREE,
            owner_token=fixture.OWNER, expires_at=expires, budget_units=2,
            lanes={"claude": {"binding": dataclasses.asdict(provider_binding), "configuration_digest": "c" * 64,
                              "cost_units": 2, "work_packet": fixture.work_packet()}})
        admission = store.admit(ValidationRequest(generation=generation, provider="claude"), fixture.OWNER)
        store.claim_execution(admission)
        output = fixture.claude_cli_native()
        capture = make_capture(admission, output, capture_key=fixture.KEY, executable_sha256=executable)
        capture_digest = store.settle(admission, output, capture)
        verifier = CaptureVerifier(store, capture_key=fixture.KEY, candidate=fixture.CANDIDATE,
                                   tree=fixture.TREE, generation=generation)
        self.assertTrue(verifier.verify(provider_binding, capture_digest))
        self.assertEqual(getattr(capture, "executable_sha256", None), executable)
        observed = self.clock_bounds()[0] - timedelta(minutes=1)
        registry = ProviderActivationRegistry(self.primary.handle.claim_store, provider_binding)
        for surface in ProviderActivationSurface:
            for index, stage in enumerate(ProviderActivationStage):
                when = observed + timedelta(seconds=index)
                registry.record(surface=surface, stage=stage, evidence_id=f"capture-{surface.value}-{index}",
                    evidence_digest=capture_digest, observed_at=when,
                    expires_at=datetime.fromtimestamp(expires, timezone.utc), now=when)
        settings = SimpleNamespace(langgraph_primary_postgres_dsn=self.dsn,
            langgraph_primary_allow_insecure_local_postgres=True,
            primary_provider_activation_bindings=lambda: {"claude": provider_binding},
            langgraph_primary_required_providers=("claude",))
        identity = SimpleNamespace(**vars(self.primary.identity), postgres_schema=self.primary.schema)
        raw_bindings = json.dumps({"claude": dataclasses.asdict(provider_binding)})
        manifest = {"provider_bindings_sha256": hashlib.sha256(raw_bindings.encode()).hexdigest()}
        descriptor = {"version": self.fixtures.evidence.CLI_RELEASE_DESCRIPTOR_VERSION,
                      "releases": [{"provider": "claude", "product": "anthropic-claude",
                                    "executable_sha256": "e" * 64}]}
        started = self.clock_bounds()[0]
        captures = self.fixtures.evidence.activation_capture_report(settings, identity, manifest,
            verifier=verifier, environment={"LANGGRAPH_PRIMARY_GENERATION_MANIFEST_SHA256": generation},
            descriptor=descriptor)
        lane = captures["lanes"]["claude"]
        self.assertEqual(lane["product"], product)
        for surface in lane["surfaces"].values():
            self.assertTrue(surface["capture_verified"])
            self.assertTrue(surface["chain_valid"])
            self.assertEqual(surface["executable_sha256"], executable)
        runtime = runtime_fixture(collected_at=started, collection_end=lambda: self.clock_bounds()[1],
            env={"LANGGRAPH_PRIMARY_GENERATION_MANIFEST_SHA256": generation,
                 "LANGGRAPH_PRIMARY_PROVIDER_ACTIVATION_BINDINGS_JSON": raw_bindings})
        # This is the real store-reader's check-12 predicate, not a TRUSTED collection PASS.
        passed, reason, _ = sc._capture_verdict(started, runtime, captures)
        self.assertIs(passed, True, reason)
        self.assertIsNone(next(item for item in sc._capture_observations(started, runtime, captures, None)
                               if item.check_id == "11").passed)


class CompletionScorecardTests(unittest.TestCase):
    def test_check_11_distinguishes_missing_executable_from_pinned_digest_mismatch(self):
        from director_orchestrator.primary_scorecard_evidence import _capture_product, CLI_RELEASE_DESCRIPTOR_VERSION
        world = World(self)
        descriptor = {"version": CLI_RELEASE_DESCRIPTOR_VERSION,
            "releases": [{"provider": "claude", "product": "anthropic-claude", "executable_sha256": "e" * 64}]}
        output = b'{"type":"result","modelUsage":{"claude-opus-5-5":{}}}'
        for executable, expected in ((None, "UNKNOWN"), ("e" * 64, "PASS"), ("f" * 64, "FAIL")):
            with self.subTest(expected=expected):
                product = _capture_product("claude", output, executable_sha256=executable, descriptor=descriptor)
                lane = world.captures["lanes"]["claude"]
                lane["product"] = product
                for surface in lane["surfaces"].values():
                    surface["product"] = product
                    surface["executable_sha256"] = executable
                self.assertEqual(world.state("11", evaluate_rules=True), expected)
        lane = world.captures["lanes"]["claude"]
        for product, expected in (("anthropic-claude-unattested", "UNKNOWN"),
                                  ("anthropic-claude-digest-mismatch", "FAIL")):
            lane["product"] = None
            lane["surfaces"]["app"]["product"] = product
            lane["surfaces"]["runtime_adapter"]["product"] = "anthropic-claude"
            self.assertEqual(world.state("11", evaluate_rules=True), expected)

    def test_backup_reads_committed_wal_and_is_query_only(self):
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / "journal.sqlite3"
            with closing(sqlite3.connect(path)) as writer:
                writer.execute("PRAGMA journal_mode=WAL")
                writer.execute("CREATE TABLE snapshot_probe (value INTEGER)")
                writer.execute("INSERT INTO snapshot_probe VALUES (1)")
                writer.commit()
                snapshot = sc._sqlite_snapshot(path)
                try:
                    writer.execute("INSERT INTO snapshot_probe VALUES (2)")
                    writer.commit()
                    self.assertEqual(snapshot.execute("SELECT value FROM snapshot_probe").fetchall(), [(1,)])
                    with self.assertRaises(sqlite3.OperationalError):
                        snapshot.execute("INSERT INTO snapshot_probe VALUES (3)")
                finally:
                    snapshot.close()

    def test_unavailable_or_invalid_backup_is_sanitized(self):
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / "private.sqlite3"
            for exists in (False, True):
                if exists:
                    path.write_bytes(b"not a SQLite database")
                with self.assertRaisesRegex(ValueError, "^SQLite snapshot unavailable or inconsistent$"):
                    sc._sqlite_snapshot(path)

