    def test_intake_forwarding_contract_01(self):
        self.assertEqual(row(collect_topology(topology()), "01")["status"], "PASS")
        # n8n forwards the gateway's bearer: a gateway holding another one cannot reach the Director.
        for name in ("ORCHESTRATOR_SHARED_SECRET", "SLACK_BOT_TOKEN"):
            rows = topology()
            rows[1]["Config"]["Env"] = [e for e in rows[1]["Config"]["Env"] if not e.startswith(name + "=")] \
                + [name + "=something-else"]
            with self.subTest(name=name):
                report = collect_topology(rows)
                self.assertEqual(row(report, "01")["status"], "FAIL")
                self.assertNotIn("something-else", json.dumps(report))
        # The whole active workflow must be the repository's: any node's settings, flags or edges.
        def headerless(nodes):
            params = node(nodes, "Create Director Task")["parameters"]["headerParameters"]
            params["parameters"] = [h for h in params["parameters"] if h["name"] != "X-Director-Intake-Signature"]

        for label, mutate in (
                ("signature header dropped", headerless),
                ("webhook basic auth", lambda nodes: node(nodes, "Slack Gateway Webhook")["parameters"].update(
                    authentication="basicAuth")),
                ("accepted not 202", lambda nodes: node(nodes, "Accepted")["parameters"]["options"].update(
                    responseCode=200)),
                ("node disabled", lambda nodes: node(nodes, "Create Director Task").update(disabled=True)),
                ("typeVersion changed", lambda nodes: node(nodes, "Exactly 202").update(typeVersion=99)),
                ("extra node", lambda nodes: nodes.append({"name": "Side Effect", "type": "n8n-nodes-base.noOp",
                                                           "parameters": {}})),
                ("node missing", lambda nodes: nodes.remove(node(nodes, "Intake Failed")))):
            workflow = workflow_fixture()
            mutate(workflow["nodes"])
            with self.subTest(label=label):
                self.assertEqual(row(collect_topology(topology(), workflow=workflow), "01")["status"], "FAIL")
        # Workflow-level settings and pinned data are part of the contract.
        for label, change in (("execution timeout", {"settings": {**INTAKE_WORKFLOW["settings"], "executionTimeout": 5}}),
                              ("execution order", {"settings": {**INTAKE_WORKFLOW["settings"], "executionOrder": "v0"}}),
                              ("pinned data", {"pin_data": {"Create Director Task": [{"json": {"statusCode": 202}}]}})):
            workflow = workflow_fixture()
            workflow.update(change)
            with self.subTest(label=label):
                self.assertEqual(row(collect_topology(topology(), workflow=workflow), "01")["status"], "FAIL")
        rewired = workflow_fixture()
        rewired["connections"]["Create Director Task"]["main"][0][0]["node"] = "Accepted"
        self.assertEqual(row(collect_topology(topology(), workflow=rewired), "01")["status"], "FAIL")
        unread = workflow_fixture()
        del unread["nodes"]
        self.assertEqual(row(collect_topology(topology(), workflow=unread), "01")["status"], "FAIL")

    def test_gateway_identities_cover_every_gateway_secret(self):
        import re
        root = Path(__file__).resolve().parents[1]
        config = (root / "src/director_orchestrator/config.py").read_text(encoding="utf-8")
        env_of = dict(re.findall(r"^\s+(\w+): str = os\.getenv\(\s*\"(\w+)\"", config, re.M))
        gateway = (root / "src/director_orchestrator/slack_bot.py").read_text(encoding="utf-8")
        read = {env_of[name] for name in re.findall(r"\bsettings\.(\w+)", gateway) if name in env_of}
        sensitive = {name for name in read if re.search(r"SECRET|TOKEN|OWNER|CHANNEL", name)}
        self.assertTrue({"SLACK_GATEWAY_SECRET", "ORCHESTRATOR_SHARED_SECRET", "SLACK_BOT_TOKEN"} <= sensitive)
        self.assertEqual(sensitive - set(sc._GATEWAY_ONLY), set(sc._GATEWAY_IDENTITIES))
        rows = topology()
        rows[1]["Config"]["Env"] = [e for e in rows[1]["Config"]["Env"] if not e.startswith("SLACK_GATEWAY_SECRET=")] \
            + ["SLACK_GATEWAY_SECRET=another-signing-secret-0123456789abc"]
        report = collect_topology(rows)
        self.assertEqual(row(report, "01")["status"], "FAIL")
        self.assertNotIn("another-signing-secret", json.dumps(report))

    def test_workflow_contracts_come_from_the_candidate_commit(self):
        self.assertEqual(row(collect_topology(topology()), "01")["status"], "PASS")
        other = json.loads(json.dumps(INTAKE_WORKFLOW))
        next(n for n in other["nodes"] if n["name"] == "Accepted")["parameters"]["options"]["responseCode"] = 201
        report = collect_topology(topology(), candidate_files={"n8n/workflows/director-intake.json":
                                                               json.dumps(other).encode()})
        self.assertEqual(row(report, "01")["status"], "FAIL")  # the active workflow is not the candidate's
        missing = collect_topology(topology(), candidate_files={"n8n/workflows/director-intake.json":
                                                                ValueError("no such blob")})
        self.assertEqual(row(missing, "01")["status"], "UNKNOWN")
        status_missing = World(self)
        status_missing.candidate_files["n8n/workflows/director-status.json"] = ValueError("no such blob")
        self.assertEqual(status_missing.state("04"), "UNKNOWN")

    def test_host_file_and_resolver_overrides_break_hops(self):
        extra = topology()
        extra[1].setdefault("HostConfig", {})["ExtraHosts"] = ["n8n:10.0.0.9"]
        self.assertEqual(row(collect_topology(extra), "01")["status"], "FAIL")
        extra_orchestrator = topology()
        extra_orchestrator[2].setdefault("HostConfig", {})["ExtraHosts"] = ["orchestrator:10.0.0.8"]
        self.assertEqual(row(collect_topology(extra_orchestrator), "01")["status"], "FAIL")
        unrelated = topology()
        unrelated[1].setdefault("HostConfig", {})["ExtraHosts"] = ["host.docker.internal:host-gateway"]
        self.assertEqual(row(collect_topology(unrelated), "01")["status"], "PASS")
        for change in ({"NetworkMode": "host"}, {"Dns": ["1.1.1.1"]}, {"DnsSearch": ["example.test"]}):
            rows = topology()
            rows[1].setdefault("HostConfig", {}).update(change)
            with self.subTest(change=change):
                self.assertEqual(row(collect_topology(rows), "01")["status"], "UNKNOWN")
        mounted = topology()
        mounted[1]["Mounts"] = [{"Destination": "/etc/hosts", "Source": "/tmp/hosts"}]
        self.assertEqual(row(collect_topology(mounted), "01")["status"], "UNKNOWN")
        world = World(self)
        world.rows[1].setdefault("HostConfig", {})["ExtraHosts"] = ["orchestrator:10.0.0.8"]
        self.assertEqual(world.state("04"), "UNKNOWN")

    def test_n8n_schema_must_be_the_default_01(self):
        for value, expected in (("public", "PASS"), ("other", "UNKNOWN")):
            rows = topology()
            rows[2]["Config"]["Env"].append("DB_POSTGRESDB_SCHEMA=" + value)
            with self.subTest(value=value):
                self.assertEqual(row(collect_topology(rows), "01")["status"], expected)

    def test_n8n_workflow_database_must_be_n8ns_own_store_01(self):
        # n8n must be able to authenticate to the queried database.
        for entry in ("POSTGRES_PASSWORD=rotated-db-secret", "POSTGRES_USER=postgres", "POSTGRES_DB=other"):
            rows = topology()
            key = entry.split("=")[0]
            rows[3]["Config"]["Env"] = [e for e in rows[3]["Config"]["Env"] if not e.startswith(key + "=")] + [entry]
            with self.subTest(entry=entry):
                report = collect_topology(rows)
                self.assertEqual(row(report, "01")["status"], "UNKNOWN")
                self.assertNotIn("rotated-db-secret", json.dumps(report))
        for change in ("DB_POSTGRESDB_HOST=external-db", "DB_TYPE=sqlite", "DB_POSTGRESDB_DATABASE=other"):
            rows = topology()
            key = change.split("=")[0]
            rows[2]["Config"]["Env"] = [entry for entry in rows[2]["Config"]["Env"]
                                        if not entry.startswith(key + "=")] + [change]
            with self.subTest(change=change):
                self.assertEqual(row(collect_topology(rows), "01")["status"], "UNKNOWN")

    def test_route_requires_cli_channel_and_gateway_in_deployment(self):
        self.assertEqual(row(collect_topology(topology()), "01")["status"], "PASS")
        report = collect_topology(topology(), channel=None)
        self.assertEqual(row(report, "01")["status"], "UNKNOWN")
        self.assertIn("--channel", row(report, "01")["explanation"])
        self.assertEqual(row(collect_topology(topology(), channel="COTHERCHAN1"), "01")["status"], "FAIL")
        foreign = topology()
        foreign[1]["Config"]["Labels"] = compose_labels("slackbot", project="director-orchestrator")
        self.assertEqual(row(collect_topology(foreign), "01")["status"], "FAIL")
        self.assertEqual(row(collect_topology(foreign, channel=None), "01")["status"], "FAIL")
        unlabelled = topology()
        del unlabelled[1]["Config"]["Labels"]
        self.assertEqual(row(collect_topology(unlabelled), "01")["status"], "UNKNOWN")
        no_n8n = [item for item in topology() if item["Id"] != N8N_DB_ID]
        self.assertEqual(row(collect_topology(no_n8n), "01")["status"], "UNKNOWN")
        # The gateway must share a network with n8n on which the relay host resolves.
        detached = topology()
        detached[1]["NetworkSettings"]["Networks"] = {"other_default": {"NetworkID": "9" * 64, "Aliases": ["slackbot"]}}
        self.assertEqual(row(collect_topology(detached), "01")["status"], "FAIL")
        unaliased = topology()
        unaliased[2]["NetworkSettings"]["Networks"][NETWORK].update(Aliases=[], DNSNames=[])
        self.assertEqual(row(collect_topology(unaliased), "01")["status"], "FAIL")
        uninspected = topology()
        del uninspected[1]["NetworkSettings"]
        self.assertEqual(row(collect_topology(uninspected), "01")["status"], "UNKNOWN")
        # n8n must reach the selected Director as orchestrator, and nothing else may answer to that name.
        cut_off = topology()
        cut_off[0]["NetworkSettings"]["Networks"] = {"other_default": {"NetworkID": "9" * 64, "Aliases": ["orchestrator"]}}
        self.assertEqual(row(collect_topology(cut_off), "01")["status"], "FAIL")
        shadowed = topology()
        shadowed.append({"Id": "6" * 64, "Name": "/another-orchestrator", "State": {"Running": True}, "Config": {},
                         "NetworkSettings": {"Networks": {NETWORK: {"NetworkID": "a" * 64, "Aliases": ["orchestrator"]}}}})
        self.assertEqual(row(collect_topology(shadowed), "01")["status"], "FAIL")
        # A competing owner on any network the source is attached to breaks the hop, not only the first shared one.
        second = topology()
        second_net = {"NetworkID": "b" * 64, "Aliases": []}
        second[1]["NetworkSettings"]["Networks"]["second"] = dict(second_net)
        second[2]["NetworkSettings"]["Networks"]["second"] = dict(second_net)
        second.append({"Id": "7" * 64, "Name": "/n8n-impostor", "State": {"Running": True}, "Config": {},
                       "NetworkSettings": {"Networks": {"second": {"NetworkID": "b" * 64, "Aliases": ["n8n"]}}}})
        self.assertEqual(row(collect_topology(second), "01")["status"], "FAIL")
        relay = topology()
        relay[1]["Config"]["Env"][3] = "N8N_DIRECTOR_WEBHOOK_URL=http://edge-engine-director-n8n-1:5678/webhook/director-intake"
        self.assertEqual(row(collect_topology(relay), "01")["status"], "PASS")
        relay[1]["Config"]["Env"][3] = "N8N_DIRECTOR_WEBHOOK_URL=http://director-orchestrator-n8n-1:5678/webhook/director-intake"
        self.assertEqual(row(collect_topology(relay), "01")["status"], "FAIL")
        self.assertNotIn(CHANNEL_FIXTURE, json.dumps(collect_topology(topology())))

    def test_channel_other_than_the_deployments_reads_no_slack_source(self):
        world = self.world()
        world.handle = Mock(side_effect=world.handle)
        report = world.report(channel="COTHERCHAN1")
        world.handle.assert_not_called()
        for key in ("03", "04", "06", "08", "09", "10", "11", "20"):
            self.assertEqual(row(report, key)["status"], "UNKNOWN")
            self.assertIn("collector not yet trusted",
                          row(report, key)["explanation"])
        self.assertEqual(row(report, "07")["status"], "UNKNOWN")

    def test_intake_drills_03(self):
        self.assertEqual(self.world(evaluate_rules=True).state("03"), "PASS")
        refused_with_task = self.world(evaluate_rules=True)
        refused_with_task.bindings[ts(100)] = (200, "DIR-LG-5E")
        self.assertEqual(refused_with_task.state("03"), "FAIL")
        refused_with_receipt = self.world(evaluate_rules=True)
        refused_with_receipt.threads[ts(100)].append({"ts": ts(102), "thread_ts": ts(100), "user": BOT,
                                                      "text": "*DIR-LG-5E — REQUEST RECEIVED*"})
        self.assertEqual(refused_with_receipt.state("03"), "FAIL")
        ambiguous_reservation = self.world(evaluate_rules=True)
        ambiguous_reservation.bindings[ts(200)] = (409, None)
        self.assertEqual(ambiguous_reservation.state("03"), "FAIL")
        duplicated = self.world(evaluate_rules=True)
        duplicated.tasks["DIR-LG-5E"]["qualification_evidence"]["task_scope_counters"]["thread_tasks"] = 2
        self.assertEqual(duplicated.state("03"), "FAIL")
        receipted_5xx = self.world(evaluate_rules=True)
        receipted_5xx.threads[ts(200)].append({"ts": ts(202), "thread_ts": ts(200), "user": BOT,
                                               "text": "*DIR-LG-5E — REQUEST RECEIVED*"})
        self.assertEqual(receipted_5xx.state("03"), "UNKNOWN")
        # Only a reply's header is a BLOCKED notice: a quoted one is not, and two notices are not one refusal.
        quoted = self.world(evaluate_rules=True)
        quoted.threads[ts(100)][1]["text"] = "Result below.\nThe docs mention *DIRECTOR — BLOCKED* replies."
        self.assertEqual(quoted.state("03"), "UNKNOWN")
        doubled = self.world(evaluate_rules=True)
        doubled.threads[ts(100)].append({**doubled.threads[ts(100)][1], "ts": ts(102)})
        self.assertEqual(doubled.state("03"), "UNKNOWN")
        tagged = self.world(evaluate_rules=True)
        tagged.threads[ts(100)][1]["text"] = ("*[[Director Gateway | fixture | 2026-09-12 | 10:00 UTC | BEGIN]]*\n\n"
                                              + tagged.threads[ts(100)][1]["text"])
        self.assertEqual(tagged.state("03"), "PASS")
        # An edited or subtyped owner post is an altered second input: the drill grades nothing.
        edited_input = self.world(evaluate_rules=True)
        edited_input.threads[ts(100)].append({"ts": ts(103), "thread_ts": ts(100), "user": OWNER, "text": "again",
                                              "edited": {"user": OWNER, "ts": ts(104)}})
        self.assertEqual(edited_input.state("03"), "UNKNOWN")
        edited_duplicate = self.world(evaluate_rules=True)
        edited_duplicate.threads[ts(300)].append({"ts": ts(305), "thread_ts": ts(300), "user": OWNER, "text": "dup",
                                                  "subtype": "thread_broadcast"})
        self.assertEqual(edited_duplicate.state("09"), "UNKNOWN")
        # A receipt quoted inside another reply is not a second receipt.
        quoted_receipt = self.world(evaluate_rules=True)
        thread = quoted_receipt.threads[ts(300)]
        thread.remove(next(m for m in thread if m.get("ts") == ts(302)))
        thread.append({"ts": ts(303), "thread_ts": ts(300), "user": BOT,
                       "text": "Note: earlier reply read *DIR-LG-D0 — REQUEST RECEIVED*"})
        self.assertEqual(quoted_receipt.state("09"), "UNKNOWN")
        # Slack intake evidence is bound to the selected gateway: recreated after the drills, or absent.
        new_gateway = self.world(evaluate_rules=True)
        new_gateway.rows[-1]["Created"] = "2026-09-12T11:00:00Z"
        self.assertEqual(new_gateway.state("03"), "UNKNOWN")
        new_n8n = self.world(evaluate_rules=True)
        new_n8n.rows[1]["Created"] = "2026-09-12T11:00:00Z"
        self.assertEqual(new_n8n.state("03"), "UNKNOWN")
        # Evidence dated after the collection had not happened when it was read.
        early_collection = self.world(evaluate_rules=True)
        early_collection.now = datetime(2026, 9, 12, 10, 50, tzinfo=timezone.utc)
        report = early_collection.report()
        self.assertEqual([row(report, key)["status"] for key in ("03", "09")], ["UNKNOWN", "UNKNOWN"])
        # A stale drill grades nothing: its negative outcome is UNKNOWN too, not FAIL.
        stale_failure = self.world(evaluate_rules=True)
        stale_failure.bindings[ts(100)] = (200, "DIR-LG-5E")
        stale_failure.rows[-1]["Created"] = "2026-09-12T11:00:00Z"
        self.assertEqual(stale_failure.state("03"), "UNKNOWN")
        # The gateway that handled the threads must hold the Director's Slack and bearer identities.
        foreign_bot = self.world(evaluate_rules=True)
        foreign_bot.rows[-1]["Config"]["Env"] = [e for e in foreign_bot.rows[-1]["Config"]["Env"]
                                                 if not e.startswith("SLACK_BOT_TOKEN=")] + ["SLACK_BOT_TOKEN=other-bot"]
        report = foreign_bot.report()
        self.assertEqual(row(report, "03")["status"], "UNKNOWN")
        self.assertNotIn("other-bot", json.dumps(report))
        report = self.world(evaluate_rules=True).report(gateway=None)
        self.assertEqual(row(report, "03")["status"], "UNKNOWN")
        self.assertIn("--gateway", row(report, "03")["explanation"])
        # One reply repeating its receipt text is one receipt: duplicate input was not exercised.
        repeated = self.world(evaluate_rules=True)
        thread = repeated.threads[ts(300)]
        thread.remove(next(m for m in thread if m.get("ts") == ts(302)))
        receipt = next(m for m in thread if m.get("ts") == ts(301))
        receipt["text"] = receipt["text"] + "\n" + receipt["text"]
        self.assertEqual(repeated.state("09"), "UNKNOWN")
        edited_refusal = self.world(evaluate_rules=True)
        edited_refusal.threads[ts(100)][1]["edited"] = {"user": BOT, "ts": ts(190)}
        self.assertEqual(edited_refusal.state("03"), "UNKNOWN")
        # Receipt text added by an edit is never parsed, so it cannot turn the drill into a FAIL either.
        forged = self.world(evaluate_rules=True)
        forged.threads[ts(100)][1].update(text="*DIR-LG-5E — REQUEST RECEIVED*", edited={"user": BOT, "ts": ts(190)})
        report = forged.report()
        self.assertEqual(row(report, "03")["status"], "UNKNOWN")
        self.assertIn("edited or subtyped", row(report, "03")["explanation"])
        unreserved = self.world(evaluate_rules=True)
        unreserved.bindings[ts(200)] = (404, None)
        self.assertEqual(unreserved.state("03"), "UNKNOWN")
        # The transport failure is its own path: a reserved task (200, one task) passes, a conflict fails.
        reserved_transport = self.world(evaluate_rules=True)
        # A task this thread's own owner post created (not another drill's task).
        reserved_transport.add(task_entry("DIR-LG-7E", 150, text="DIRECTOR drill"), thread=False)
        reserved_transport.bindings[ts(150)] = (200, "DIR-LG-7E")
        self.assertEqual(reserved_transport.state("03"), "PASS")
        borrowed_transport = self.world(evaluate_rules=True)
        borrowed_transport.bindings[ts(150)] = (200, "DIR-LG-5E")  # another thread's task: not correlated
        self.assertEqual(borrowed_transport.state("03"), "UNKNOWN")
        conflicting_transport = self.world(evaluate_rules=True)
        conflicting_transport.bindings[ts(150)] = (409, None)
        self.assertEqual(conflicting_transport.state("03"), "FAIL")
        answered = self.world(evaluate_rules=True)
        answered.threads[ts(150)].append({"ts": ts(152), "thread_ts": ts(150), "user": BOT,
                                          "text": "*DIR-LG-5E — REQUEST RECEIVED*"})
        self.assertEqual(answered.state("03"), "UNKNOWN")
        report = self.world(evaluate_rules=True).report(drill_threads={"refusal-4xx": ts(100), "reserved-5xx": ts(200)})
        self.assertEqual(row(report, "03")["status"], "UNKNOWN")
        self.assertIn("transport-failure", row(report, "03")["explanation"])
        report = self.world(evaluate_rules=True).report(drill_threads={"refusal-4xx": ts(100)})
        self.assertEqual(row(report, "03")["status"], "UNKNOWN")
        self.assertIn("reserved-5xx", row(report, "03")["explanation"])
        unavailable = self.world(evaluate_rules=True)
        unavailable.failing.add(ts(100))
        self.assertEqual(unavailable.state("03"), "UNKNOWN")
        report = self.world(evaluate_rules=True).report(channel=None)
        self.assertEqual(row(report, "03")["status"], "UNKNOWN")
        self.assertIn("--channel", row(report, "03")["explanation"])
        # A drill posted before the running container was created cannot attest it (the 404 drill has no task).
        recreated = self.world(evaluate_rules=True)
        # After every drill thread and its task ran (10:48:20-10:54:05).
        recreated.rows[0]["Created"] = recreated.rows[0]["State"]["StartedAt"] = "2026-09-12T10:55:00Z"
        report = recreated.report()
        self.assertEqual([row(report, key)["status"] for key in ("03", "09")], ["UNKNOWN", "UNKNOWN"])
        self.assertIn("refusal-4xx", row(report, "03")["explanation"])
        # Nor can a drill whose bound task was created before it.
        early_task = self.world(evaluate_rules=True)
        early_task.tasks["DIR-LG-5E"]["qualification_evidence"]["task_created_at"] = "2026-09-12T08:59:00+00:00"
        explanation = row(early_task.report(), "03")["explanation"]
        self.assertIn("reserved-5xx", explanation)
        self.assertNotIn("refusal-4xx", explanation)

    def test_status_execution_04(self):
        self.assertEqual(self.world(evaluate_rules=True).state("04"), "PASS")
        wrong_message = self.world(evaluate_rules=True)
        wrong_message.threads[STATUS_TS][0]["text"] = "an unrelated post"
        self.assertEqual(wrong_message.state("04"), "FAIL")
        # The newest scheduled run is graded before any older successful post.
        failing_now = self.world(evaluate_rules=True)
        failing_now.status["latest"] = {"id": "4420", "status": "error", "finished": True,
                                        "startedAt": "2026-09-12T09:59:30+00:00",
                                        "stoppedAt": "2026-09-12T09:59:31+00:00"}
        self.assertEqual(failing_now.state("04"), "FAIL")
        running = self.world(evaluate_rules=True)
        running.status["latest"] = {"id": "4421", "status": "running", "finished": False,
                                    "startedAt": "2026-09-12T09:59:30+00:00", "stoppedAt": None}
        self.assertEqual(running.state("04"), "UNKNOWN")
        quiet_success = self.world(evaluate_rules=True)
        quiet_success.status["latest"] = {"id": "4422", "status": "success", "finished": True,
                                          "startedAt": "2026-09-12T09:59:30+00:00",
                                          "stoppedAt": "2026-09-12T09:59:31+00:00"}
        self.assertEqual(quiet_success.state("04"), "PASS")  # nothing to post, but the workflow is healthy
        # The post must postdate the Post Status credential's latest update, which must be readable.
        for credential_at in ("2026-09-12T09:59:30+00:00", None):
            case = self.world(evaluate_rules=True)
            case.status["execution"]["credential_updated_at"] = credential_at
            with self.subTest(credential_at=credential_at):
                self.assertEqual(case.state("04"), "UNKNOWN")
        future_latest = self.world(evaluate_rules=True)
        future_latest.status["latest"].update(startedAt="2026-09-12T21:00:00+00:00",
                                              stoppedAt="2026-09-12T21:00:01+00:00")
        self.assertEqual(future_latest.state("04"), "UNKNOWN")
        other_text = self.world(evaluate_rules=True)
        run = {"resultData": {"runData": {"Post Status": [{"data": {"main": [[{"json": {
            "ok": True, "channel": CHANNEL_FIXTURE, "ts": STATUS_TS,
            "message": {"text": "*STATUS — something else*"}}}]]}}]}}}
        other_text.status["execution"]["data"] = flatted(run)
        self.assertEqual(other_text.state("04"), "FAIL")
        human = self.world(evaluate_rules=True)
        del human.threads[STATUS_TS][0]["bot_id"]
        self.assertEqual(human.state("04"), "FAIL")
        for status in ({"workflows": 1, "execution": None}, {"workflows": 2, "execution": status_fixture()["execution"]},
                       status_fixture(channel="COTHERCHAN1"), status_fixture(ok=False),
                       status_fixture(ts_value="1789207999.000100"), None, {"workflows": 1, "execution": {"data": "[{}"}}):
            case = self.world(evaluate_rules=True)
            case.status = status
            with self.subTest(status=status):
                self.assertEqual(case.state("04"), "UNKNOWN")
        incomplete = self.world(evaluate_rules=True)
        incomplete.failing.add(STATUS_TS)
        self.assertEqual(incomplete.state("04"), "UNKNOWN")
        edited = self.world(evaluate_rules=True)
        edited.threads[STATUS_TS][0]["edited"] = {"user": BOT, "ts": ts(90)}
        self.assertEqual(edited.state("04"), "UNKNOWN")
        inactive = self.world(evaluate_rules=True)
        inactive.status["execution"]["workflow_active"] = False
        self.assertEqual(inactive.state("04"), "UNKNOWN")
        new_n8n = self.world(evaluate_rules=True)
        new_n8n.rows[1]["Created"] = "2026-09-12T09:59:30Z"
        self.assertEqual(new_n8n.state("04"), "UNKNOWN")
        # The whole active status workflow must be the repository's (only deploy-time fields and the bound
        # channel may differ): code, texts, the health response options, flags, credential type and edges.
        for label, mutate in (
                ("static diff code", lambda nodes: node(nodes, "Diff Readiness")["parameters"].update(
                    jsCode="return [{json: {text: '*STATUS — ok*'}}];")),
                ("static post text", lambda nodes: node(nodes, "Post Status")["parameters"].update(
                    text="*STATUS — static*")),
                ("other channel", lambda nodes: node(nodes, "Post Status")["parameters"]["channelId"].update(
                    value="COTHERCHAN1")),
                ("health without full response", lambda nodes: node(nodes, "Read Health")["parameters"]["options"].pop(
                    "response")),
                ("credential type", lambda nodes: node(nodes, "Post Status").update(
                    credentials={"slackOAuth2Api": {"id": "x", "name": "y"}})),
                ("disabled trigger", lambda nodes: node(nodes, "Every 5 minutes").update(disabled=True)),
                ("node missing", lambda nodes: nodes.remove(node(nodes, "Diff Readiness")))):
            case = self.world(evaluate_rules=True)
            mutate(case.status["execution"]["active_nodes"])
            with self.subTest(label=label):
                self.assertEqual(case.state("04"), "UNKNOWN")
        rewired = self.world(evaluate_rules=True)
        rewired.status["execution"]["active_connections"]["Read Health"]["main"][0][0]["node"] = "Post Status"
        self.assertEqual(rewired.state("04"), "UNKNOWN")
        for change in ({"workflow_settings": {**STATUS_WORKFLOW["settings"], "saveDataSuccessExecution": "none"}},
                       {"pin_data": {"Read Health": [{"json": {}}]}}):
            case = self.world(evaluate_rules=True)
            case.status["execution"].update(change)
            with self.subTest(change=change):
                self.assertEqual(case.state("04"), "UNKNOWN")
        # An execution that stopped after the collection is future-dated.
        future = self.world(evaluate_rules=True)
        future.now = datetime(2026, 9, 12, 9, 59, 1, tzinfo=timezone.utc)
        self.assertEqual(future.state("04"), "UNKNOWN")
        # Another bot at the correlated ts is not the Director's status post.
        other_bot = self.world(evaluate_rules=True)
        other_bot.threads[STATUS_TS][0]["user"] = "UOTHERBOT1"
        self.assertEqual(other_bot.state("04"), "FAIL")
        # n8n's executions are read only from the store n8n itself is configured to use.
        elsewhere = self.world(evaluate_rules=True)
        n8n_row = next(item for item in elsewhere.rows if item["Id"] == N8N_ID)
        n8n_row["Config"]["Env"] = [e for e in n8n_row["Config"]["Env"] if not e.startswith("DB_POSTGRESDB_HOST=")] \
            + ["DB_POSTGRESDB_HOST=external-db"]
        self.assertEqual(elsewhere.state("04"), "UNKNOWN")
        # The execution must have run the active version.
        for change in ({"execution_version": "v-1"}, {"active_version_at": "2026-09-12T09:59:30+00:00"},
                       {"workflow_updated_at": "2026-09-12T09:59:30+00:00"}, {"active_version_at": None}):
            case = self.world(evaluate_rules=True)
            case.status["execution"].update(change)
            with self.subTest(change=change):
                self.assertEqual(case.state("04"), "UNKNOWN")
        recorded = self.world(evaluate_rules=True)
        recorded.status["execution"]["execution_version"] = "v-2"
        self.assertEqual(recorded.state("04"), "PASS")
        # n8n resolving orchestrator to another container cannot attest the selected Director.
        detached = self.world(evaluate_rules=True)
        detached.rows[0]["NetworkSettings"]["Networks"] = {"other_default": {"NetworkID": "9" * 64,
                                                                             "Aliases": ["orchestrator"]}}
        self.assertEqual(detached.state("04"), "UNKNOWN")
        # The execution started at 09:59:00; a container created after it was not the poster.
        recreated = self.world(evaluate_rules=True)
        recreated.rows[0]["Created"] = recreated.rows[0]["State"]["StartedAt"] = "2026-09-12T09:59:30Z"
        report = recreated.report()
        self.assertEqual(row(report, "04")["status"], "UNKNOWN")
        self.assertIn("before the running Director", row(report, "04")["explanation"])

    def test_flatted_decoder_resolves_shared_and_cyclic_references(self):
        self.assertEqual(sc._flatted(flatted({"a": ["x", 1, None, {"b": "y"}]})), {"a": ["x", 1, None, {"b": "y"}]})
        cyclic = sc._flatted('[{"self":"0","name":"1"},"n"]')
        self.assertIs(cyclic["self"], cyclic)
        for bad in ('{"a":1}', "[]", '[{"a":"9"}]', '[{"a":"x"}]'):
            with self.subTest(bad=bad), self.assertRaises(ValueError):
                sc._flatted(bad)

    def test_status_workflow_saves_success_executions_for_check_04(self):
        workflow = json.loads((Path(__file__).resolve().parents[1] / "n8n/workflows/director-status.json").read_text(encoding="utf-8"))
        settings = workflow["settings"]
        self.assertEqual(settings["saveDataSuccessExecution"], "all")
        self.assertIs(settings["saveManualExecutions"], False)
        self.assertIs(settings["saveExecutionProgress"], False)
        self.assertEqual(workflow["name"], "Director Status")
        self.assertIn("Post Status", {node["name"] for node in workflow["nodes"]})

    def test_approval_restart_06_08(self):
        report = self.world(evaluate_rules=True).report()
        self.assertEqual([row(report, key)["status"] for key in ("06", "08")], ["PASS", "PASS"])
        redispatched = self.world(evaluate_rules=True)
        readback = redispatched.tasks[APPROVAL_TASK]["qualification_evidence"]
        # A second dispatch, in the product's order: attempt 1 failed, attempt 2 ran after it and succeeded, then
        # the assignment settled (the shared lifecycle and settlement rules refuse any other order).
        first = json.loads(json.dumps(readback["provider_attempts"]))
        last = max(datetime.fromisoformat(event["recorded_at"]) for event in first)
        # A transient transport failure: the only failure primary_parallel authorizes a retry after (4110399582).
        readback["provider_attempts"][-1].update(status="FAILED", result_digest=None,
                                                 reason_code="provider_transient_transport_failure")
        for index, event in enumerate(first, 1):
            event.update(attempt_ordinal=2, attempt_digest="sha256:" + "3" * 64,
                         recorded_at=(last + timedelta(seconds=index)).isoformat())
            if index == len(first):
                event.update(status="SUCCEEDED", result_digest=readback["assignments"][0]["result_digest"],
                             reason_code="attempt_succeeded")
            readback["provider_attempts"].append(event)
        readback["assignments"][0]["completed_at"] = (last + timedelta(seconds=len(first) + 1)).isoformat()
        # The second attempt holds its own spend reservation, with its usage recorded.
        readback["provider_usage"].append({**readback["provider_usage"][0], "attempt_digest": "sha256:" + "3" * 64})
        tf.recount(readback)
        self.assertEqual(redispatched.state("06"), "FAIL")
        early = self.world(evaluate_rules=True)
        early.add(approval_entry(decided=iso(1789210000 + 30002)))
        # A decision before its prompt breaks the shared delivery rule (decision_follows_prompt, 4110553569): the
        # readback carrying it is refused, so 08 cannot be graded on it, and the global count fails 07.
        self.assertEqual(early.state("08"), "UNKNOWN")
        impostor = self.world(evaluate_rules=True)
        impostor.threads[ts(30000)][2]["user"] = OWNER
        self.assertEqual(impostor.state("08"), "FAIL")
        stale_impostor = self.world(evaluate_rules=True)
        stale_impostor.threads[ts(30000)][2]["user"] = OWNER
        stale_impostor.rows[-1]["Created"] = "2026-09-12T19:06:42Z"  # the gateway, recreated after the task
        self.assertEqual([row(stale_impostor.report(), key)["status"] for key in ("06", "08")], ["UNKNOWN", "UNKNOWN"])
        reworded = self.world(evaluate_rules=True)
        section = reworded.threads[ts(30000)][2]["blocks"][0]["text"]
        # A line no stock phrase covers: only the exact rendering catches it.
        assert "Approve or reject this exact request" in section["text"]
        section["text"] = section["text"].replace("Approve or reject this exact request", "Approve this request")
        self.assertEqual(reworded.state("08"), "UNKNOWN")
        # An external-effect approval renders its persisted effect grant: equal with it, unknown without it.
        grant = {"action": "github.pr.comment", "target": "edwardjones3976/director-orchestrator#1"}
        effect = self.world(evaluate_rules=True)
        effect_entry = effect.add(approval_entry(kind="external_effect", grant=grant))
        effect.consistency["tasks"][APPROVAL_TASK]["application"] = effect_entry["application"]
        # The graph's effect approval binding names the effect this request authorized (director_primary_effect_
        # approval_binding); its execution starts after the authorization (review 4107814573).
        effect_key = effect_entry["task"]["qualification_evidence"]["effects"][0]["effect_key_digest"]
        effect.consistency["tasks"][APPROVAL_TASK]["effect_approval_bindings"] = [
            {"effect_key_digest": effect_key, "approval_request_digest": "sha256:" + "8" * 64}]
        self.assertEqual(effect.state("08"), "PASS")
        unbound_effect = self.world(evaluate_rules=True)
        unbound_effect.add(approval_entry(kind="external_effect", grant=grant))
        unbound_effect.consistency["tasks"][APPROVAL_TASK]["application"] = effect_entry["application"]
        self.assertEqual(unbound_effect.state("08"), "UNKNOWN")  # no binding names the approved effect
        early_effect = self.world(evaluate_rules=True)
        early_entry = early_effect.add(approval_entry(kind="external_effect", grant=grant))
        early_effect.consistency["tasks"][APPROVAL_TASK]["application"] = effect_entry["application"]
        early_effect.consistency["tasks"][APPROVAL_TASK]["effect_approval_bindings"] = [
            {"effect_key_digest": effect_key, "approval_request_digest": "sha256:" + "8" * 64}]
        started = early_entry["task"]["qualification_evidence"]["effects"][0]
        started.update(reserved_at=iso(1789210000 + 30006), execution_started_at=iso(1789210000 + 30007))
        self.assertEqual(early_effect.state("08"), "FAIL")  # executed before its approval was authorized
        early_run = self.world(evaluate_rules=True)
        early_run.tasks[APPROVAL_TASK]["qualification_evidence"]["provider_attempts"][0]["recorded_at"] = iso(
            1789210000 + 30008.5)  # the first attempt began before the execution approval (claimed at 30009)
        early_run.tasks[APPROVAL_TASK]["qualification_evidence"]["assignments"][0]["reserved_at"] = iso(
            1789210000 + 30008)
        self.assertEqual(early_run.state("08"), "FAIL")
        stripped = {key: value for key, value in effect_entry["application"].items() if key != "effect_grant"}
        effect.consistency["tasks"][APPROVAL_TASK]["application"] = stripped
        self.assertEqual(effect.state("08"), "UNKNOWN")
        # Every block field counts; only Slack's own block_id and plain_text emoji flag are ignored.
        slack_added = self.world(evaluate_rules=True)
        blocks = slack_added.threads[ts(30000)][2]["blocks"]
        for index, block in enumerate(blocks):
            block["block_id"] = f"slack-{index}"
            if block.get("type") == "section":
                block["text"]["emoji"] = True
        self.assertEqual(slack_added.state("08"), "PASS")
        for label, mutate in (
                ("section fields", lambda b: b[0].update(fields=[{"type": "mrkdwn", "text": "extra scope"}])),
                ("accessory", lambda b: b[0].update(accessory={"type": "button", "text": {"type": "plain_text",
                                                                                          "text": "More"}})),
                ("confirm dialog", lambda b: b[-1]["elements"][0].update(confirm={"title": {"type": "plain_text",
                                                                                            "text": "Sure?"}})),
                ("button url", lambda b: b[-1]["elements"][0].update(url="https://example.test")),
                ("button style", lambda b: b[-1]["elements"][0].update(style="danger"))):
            case = self.world(evaluate_rules=True)
            mutate(case.threads[ts(30000)][2]["blocks"])
            with self.subTest(label=label):
                self.assertEqual(case.state("08"), "UNKNOWN")
        partial = self.world(evaluate_rules=True)
        partial.incomplete.add(ts(30000))
        self.assertEqual(partial.state("08"), "UNKNOWN")
        for change in ("wrong button", "wrong kind text"):
            case = self.world(evaluate_rules=True)
            prompt = case.threads[ts(30000)][2]
            if change == "wrong button":
                prompt["blocks"][1]["elements"][0]["value"] = prompt["blocks"][1]["elements"][0]["value"].replace(
                    "sha256:" + "8" * 64, "sha256:" + "0" * 64)
            else:
                prompt["blocks"][0]["text"]["text"] = "Something else entirely"
            with self.subTest(change=change):
                self.assertEqual(case.state("08"), "UNKNOWN")
        edited_prompt = self.world(evaluate_rules=True)
        edited_prompt.threads[ts(30000)][2]["edited"] = {"user": BOT, "ts": ts(30020)}
        self.assertEqual(edited_prompt.state("08"), "UNKNOWN")
        unscoped = self.world(evaluate_rules=True)
        # record_owner_decision writes decision, time and command together (4110399587): with none of them the
        # control plane's receipt belongs to no approved delivery, which fails (review 4100880210) ...
        unscoped.tasks[APPROVAL_TASK]["qualification_evidence"]["slack_deliveries"][-1].update(
            owner_decision=None, owner_decision_at=None, owner_command_id=None)
        self.assertEqual(unscoped.state("08"), "FAIL")
        # ... and a decision missing only its command is not the producer's row: the readback is refused.
        partial = self.world(evaluate_rules=True)
        partial.tasks[APPROVAL_TASK]["qualification_evidence"]["slack_deliveries"][-1]["owner_command_id"] = None
        self.assertEqual(partial.state("08"), "UNKNOWN")
        # The decision must match a control-plane approval_resume receipt, re-read, not only the delivery row.
        unreceipted = self.world(evaluate_rules=True)
        unreceipted.consistency["tasks"][APPROVAL_TASK]["approval_receipts"] = []
        self.assertEqual(unreceipted.state("08"), "UNKNOWN")
        retimed = self.world(evaluate_rules=True)
        retimed.consistency["tasks"][APPROVAL_TASK]["approval_receipts"] = [approval_receipt(iso(1789210000 + 30011))]
        self.assertEqual(retimed.state("08"), "FAIL")  # a receipt no delivery accounts for
        # The receipt must join the owner's durable, signature-verified command authorization.
        for change in ({"authorized": False}, {"authorized_command_digest": False}, {"authorized_fence": False},
                       {"proof_version": "v0"}, {"actor_id": "USOMEONEELSE"},
                       {"authorization_claimed_at": iso(1789210000 + 30011)},
                       {"authorization_proof_expires_at": iso(1789210000 + 30009)},
                       {"authorization_claimed_at": None}):
            case = self.world(evaluate_rules=True)
            case.consistency["tasks"][APPROVAL_TASK]["approval_receipts"][0].update(change)
            with self.subTest(change=change):
                self.assertEqual(case.state("08"), "FAIL")  # the unverifiable receipt is unaccounted for
        other_command = self.world(evaluate_rules=True)
        other_command.consistency["tasks"][APPROVAL_TASK]["approval_receipts"][0]["command_id_sha256"] = "0" * 64
        self.assertEqual(other_command.state("08"), "FAIL")
        no_snapshot = self.world(evaluate_rules=True)
        no_snapshot.consistency = None
        self.assertEqual([row(no_snapshot.report(), key)["status"] for key in ("06", "08")], ["PASS", "UNKNOWN"])
        queued_only = self.world(evaluate_rules=True)
        queued_only.tasks[APPROVAL_TASK]["qualification_evidence"]["slack_deliveries"][-1]["created_at"] = (
            iso(1789210000 + 30010))  # enqueued only after the restart
        self.assertEqual(queued_only.state("06"), "UNKNOWN")
        # A terminal notification enqueued after the restart is not a resume without a post-start graph step.
        notification_only = self.world(evaluate_rules=True)
        readback = notification_only.tasks[APPROVAL_TASK]["qualification_evidence"]
        for event in readback["provider_attempts"]:
            event["recorded_at"] = "2026-09-12T09:25:00+00:00"
        readback["task_updated_at"] = "2026-09-12T09:26:00+00:00"
        self.assertEqual(notification_only.state("06"), "UNKNOWN")
        late_start = self.world(evaluate_rules=True)
        late_start.rows[0]["State"]["StartedAt"] = "2026-09-12T19:30:00Z"  # after the approval task ran (~19:07)
        self.assertEqual(late_start.state("06"), "UNKNOWN")
        # An approval task created before the running container cannot attest it.
        recreated = self.world(evaluate_rules=True)
        recreated.rows[0]["Created"] = recreated.rows[0]["State"]["StartedAt"] = "2026-09-12T19:06:42Z"
        report = recreated.report()
        self.assertEqual(row(report, "08")["status"], "UNKNOWN")
        self.assertIn("before the running Director container", row(report, "08")["explanation"])
        report = self.world().report(approval_task=None)
        for key in ("06", "08"):
            self.assertEqual(row(report, key)["status"], "UNKNOWN")
            self.assertEqual(row(report, key)["explanation"],
                             "collector not yet trusted")
        missing = self.world(evaluate_rules=True)
        del missing.tasks[APPROVAL_TASK]
        report = missing.report()
        self.assertEqual([row(report, key)["status"] for key in ("06", "08")], ["UNKNOWN", "UNKNOWN"])

    def test_generation_tree_must_match_the_runtime_label_and_commit(self):
        for mutate in (lambda w: w.rows[0]["Config"]["Labels"].update({"org.director.candidate.tree": "e" * 40}),
                       lambda w: w.consistency["generation"].update(candidate_tree="e" * 40),
                       lambda w: setattr(w, "commit_tree", "e" * 40)):
            world = self.world()
            mutate(world)
            with self.subTest(mutate=mutate):
                self.assertEqual(world.state("07"), "UNKNOWN")

    def test_generation_commit_must_match_the_runtime_label(self):
        world = self.world()
        world.consistency["generation"]["candidate_commit"] = OTHER
        report = world.report()
        for key in ("07", "11", "12", "17"):
            self.assertEqual(row(report, key)["status"], "UNKNOWN", key)
        self.assertEqual(row(report, "07")["explanation"], "collector not yet trusted")
        # The generation manifest the snapshot was verified against must be the one the container pins (#4107814604).
        other_manifest = self.world()
        other_manifest.consistency["generation"]["manifest_sha256"] = "0" * 64
        report = other_manifest.report()
        for key in ("07", "08", "15", "17", "20"):
            self.assertEqual(row(report, key)["status"], "UNKNOWN", key)

    def test_consistency_07(self):
        self.assertEqual(self.world(evaluate_rules=True).state("07"), "PASS")
        conflicted = self.world(evaluate_rules=True)
        conflicted.consistency["counts"]["projection_batch_digest_conflicts"] = 1
        self.assertEqual(conflicted.state("07"), "FAIL")
        blocked = self.world(evaluate_rules=True)
        blocked.payload["langgraph_primary"]["historical_parallel_plan_hold_count"] = 1
        self.assertEqual(blocked.state("07"), "FAIL")
        busy = self.world(evaluate_rules=True)
        busy.consistency["counts"]["live_writer_claims"] = 1
        self.assertEqual(busy.state("07"), "UNKNOWN")
        future_snapshot = self.world(evaluate_rules=True)
        future_snapshot.consistency["captured_at"] = "2026-09-12T21:00:00+00:00"
        self.assertEqual(future_snapshot.state("07"), "UNKNOWN")
        held = self.world(evaluate_rules=True)
        held.consistency["counts"]["pending_owner_decisions"] = 1
        self.assertEqual(held.state("07"), "UNKNOWN")
        for key in ("succeeded_projections_with_unsucceeded_assignments", "projections_missing_batch",
                    "batches_without_projection"):
            case = self.world(evaluate_rules=True)
            case.consistency["counts"][key] = 1
            with self.subTest(key=key):
                self.assertEqual(case.state("07"), "FAIL")
        for change in ({"generation": {**consistency_fixture()["generation"], "manifest_sha256": "0" * 64}},
                       {"intake_fencing_generation": 82}, {"counts": {"projection_batch_digest_conflicts": 0}}):
            case = self.world(evaluate_rules=True)
