    def test_rows_keep_their_producers_contract_inside_the_tasks_lifetime(self):
        """4110241997: no child row predates its task's creation. 4110241987: every delivery state carries exactly
        PrimarySlackDelivery's fields. 4110241982: a reconciliation event after its claim's terminal evidence is a
        conflict, never hidden by the earlier terminal row. All through task_evidence_errors, the per-task and
        global paths' one rule."""
        import copy
        from director_orchestrator.primary_scorecard_evidence import task_evidence_errors

        def errors(readback):
            return {key: value for key, value in task_evidence_errors(readback)[1].items() if value}

        base = tf.readback_fixture()
        self.assertEqual(errors(base), {})
        missing = copy.deepcopy(base)
        del missing["task_created_at"]
        self.assertIn("lifecycle", errors(missing))
        for section, field in (("assignments", "reserved_at"), ("provider_attempts", "recorded_at"),
                               ("effects", "reserved_at"), ("slack_deliveries", "created_at"),
                               ("status_receipts", "created_at")):
            early = copy.deepcopy(base)
            early[section][0][field] = "2026-09-12T09:59:59+00:00"  # one second before the task was created
            with self.subTest(section=section):
                self.assertIn("lifecycle", errors(early))
        delivered = base["slack_deliveries"][0]
        unclaimed = {"claimed_at": None, "acknowledged_at": None, "delivered_at": None, "slack_ts": None,
                     "readback_attempts": 0}
        claimed = {**unclaimed, "claimed_at": delivered["claimed_at"]}
        conforming = {"PENDING": unclaimed, "SUPPRESSED": unclaimed, "SUPERSEDED": unclaimed, "POSTING": claimed,
                      "REFUSED": {**claimed, "last_error": "slack_refused"},
                      "AMBIGUOUS": {**claimed, "readback_attempts": 2, "last_error": "readback_unverified"},
                      "ACKNOWLEDGED": {**claimed, "acknowledged_at": delivered["acknowledged_at"],
                                       "slack_ts": delivered["slack_ts"], "readback_attempts": 1}}
        breaking = {"PENDING": {"readback_attempts": 1}, "SUPPRESSED": {"slack_ts": delivered["slack_ts"]},
                    "SUPERSEDED": {"acknowledged_at": delivered["acknowledged_at"]},
                    "POSTING": {"claimed_at": None}, "REFUSED": {"claimed_at": None},
                    "AMBIGUOUS": {"slack_ts": delivered["slack_ts"]}, "ACKNOWLEDGED": {"slack_ts": None}}
        # 4111082596: last_error per state, from the producer's fixed set.
        error_breaking = {"PENDING": {"last_error": "slack_refused"}, "SUPPRESSED": {"last_error": "x"},
                          "SUPERSEDED": {"last_error": "post_ack_missing"}, "POSTING": {"last_error": "slack_refused"},
                          "REFUSED": {"last_error": None}, "AMBIGUOUS": {"last_error": "slack_refused"},
                          "ACKNOWLEDGED": {"last_error": "readback_unverified", "readback_attempts": 0}}
        for index, (state, fields) in enumerate(conforming.items()):
            def with_row(extra):
                readback = copy.deepcopy(base)
                readback["slack_deliveries"].append({**delivered, **fields, **extra, "state": state,
                                                     "notification_key": "hold:sha256:" + str(index) * 64,
                                                     "client_msg_id": f"message-{index}"})
                return errors(readback)
            with self.subTest(state=state):
                self.assertEqual(with_row({}), {})
                self.assertIn("lifecycle", with_row(breaking[state]))
                self.assertIn("lifecycle", with_row(error_breaking[state]))
        from director_orchestrator.primary_scorecard_evidence import delivery_error_contract
        self.assertTrue(delivery_error_contract({"state": "REFUSED", "last_error": "slack_rate_limited:retry_after=30",
                                                 "readback_attempts": 0}))
        self.assertTrue(delivery_error_contract({"state": "AMBIGUOUS", "last_error": "post_ack_invalid",
                                                 "readback_attempts": 0}))
        self.assertFalse(delivery_error_contract({"state": "AMBIGUOUS", "last_error": "readback_unverified",
                                                  "readback_attempts": 0}))
        self.assertFalse(delivery_error_contract({**delivered, "last_error": "readback_unverified"}))  # DELIVERED
        effect = base["effects"][0]
        for recorded, broken in ((effect["terminal_recorded_at"], False), ("2026-09-12T10:00:50+00:00", True),
                                 ("2026-09-12T10:00:01+00:00", True)):  # at, after the terminal row; before reservation
            readback = copy.deepcopy(base)
            readback["reconciliation_events"] = [{"event_id": 1, "claim_key": effect["claim_key"], "state": "AMBIGUOUS",
                                                  "evidence_digest": "sha256:" + "9" * 64, "recorded_at": recorded,
                                                  "authority_matches": True}]
            with self.subTest(recorded=recorded):
                self.assertEqual("effects" in errors(readback), broken)

    def test_retries_decisions_bindings_and_projection_digests_keep_their_producers_rules(self):
        """4110399582: a later ordinal only after a retry-authorizing failure, never after SUCCEEDED. 4110399587:
        decision, time and command all or none. 4110399589: a remote binding only after an execution claim, and a
        bound effect without terminal evidence is unsettled. 4110399590: projection digests well formed, the approval
        key's and the terminal row's joined; the producer identity where the schema is known."""
        import copy
        import uuid
        from director_orchestrator.primary_scorecard_evidence import task_evidence_errors

        def result(readback):
            _, errors, states = task_evidence_errors(tf.recount(readback) or readback)
            return {key: value for key, value in errors.items() if value}, states

        base = tf.readback_fixture()

        def retried(status="FAILED", reason="provider_transient_transport_failure", start="2026-09-12T10:00:26+00:00"):
            readback = copy.deepcopy(base)
            readback["provider_attempts"][1].update(status=status, reason_code=reason,
                                                    result_digest=None if status != "SUCCEEDED" else
                                                    readback["provider_attempts"][1]["result_digest"])
            second = [{**event, "attempt_ordinal": 2, "attempt_digest": "sha256:" + "a" * 64,
                       "idempotency_key_digest": "sha256:" + "c" * 64,
                       "recorded_at": start if index == 0 else "2026-09-12T10:00:27+00:00"}
                      for index, event in enumerate(base["provider_attempts"])]
            readback["provider_attempts"].extend(second)
            readback["assignments"][0]["completed_at"] = "2026-09-12T10:00:28+00:00"
            readback["provider_usage"].append({**readback["provider_usage"][0], "attempt_digest": "sha256:" + "a" * 64})
            return result(readback)[0]

        self.assertEqual(retried(), {})
        for label, case in (("after SUCCEEDED", {"status": "SUCCEEDED", "reason": "attempt_succeeded"}),
                            ("after a terminal failure", {"reason": "attempt_failed"}),
                            ("after AMBIGUOUS", {"status": "AMBIGUOUS", "reason": "callback_timeout"}),
                            ("before its predecessor settled", {"start": "2026-09-12T10:00:08+00:00"})):
            with self.subTest(label):
                self.assertIn("attempts", retried(**case))
        delivered = base["slack_deliveries"][0]
        projection = base["projection_digest"]
        approval = {**delivered, "notification_key": "approval:sha256:" + "8" * 64 + ":" + projection,
                    "projection_digest": projection, "client_msg_id": "approval-message", "owner_decision": "approve",
                    "owner_decision_at": "2026-09-12T10:00:40+00:00", "owner_command_id": "command-1"}

        def delivery(row, **sections):
            readback = copy.deepcopy(base)
            readback["slack_deliveries"].append(row)
            readback.update(sections)
            return result(readback)

        self.assertEqual(delivery(approval)[0], {})
        for field in ("owner_decision", "owner_decision_at", "owner_command_id"):
            with self.subTest(missing=field):
                self.assertIn("deliveries", delivery({**approval, field: None})[0])
        self.assertIn("deliveries", delivery({**approval, "projection_digest": "not-a-digest"})[0])
        self.assertIn("deliveries", delivery({**approval, "projection_digest": "sha256:" + "0" * 64})[0])
        stale = copy.deepcopy(base)
        stale["slack_deliveries"][0]["projection_digest"] = "sha256:" + "0" * 64
        self.assertEqual(result(stale)[1]["deliveries"][0], "conflict")
        # Where the schema is known (the global path), the identity is enqueue's uuid5.
        schema = "director_primary_v1"
        produced = str(uuid.uuid5(uuid.NAMESPACE_URL, f"{schema}:{base['task_id']}:{approval['notification_key']}"))
        # The fixture's terminal row carries the producer identity for this schema.
        self.assertEqual(delivered["client_msg_id"],
                         str(uuid.uuid5(uuid.NAMESPACE_URL, f"{schema}:{base['task_id']}:terminal")))
        self.assertEqual(delivery({**approval, "client_msg_id": produced}, schema=schema)[0], {})
        self.assertIn("deliveries", delivery(approval, schema=schema)[0])
        unexecuted = copy.deepcopy(base)
        unexecuted["effects"][0]["execution_started_at"] = None
        self.assertIn("effects", result(unexecuted)[0])
        bound = {"effects": [{**base["effects"][0], "execution_started_at": None, "terminal_disposition": None}]}
        row_of = {"qualification_evidence": {"effect_state": "PROVIDER_EFFECT_RECORDED"}}
        self.assertIsNone(sc._ambiguous_effects(row_of, {**base, **bound}, {"a": {"status": "SUCCEEDED"}}))
        # The graded terminal delivery must name the record's projection (checks 09, 10 and 20 via _final_correlated).
        world = self.world(evaluate_rules=True)
        terminal_row = next(r for r in world.tasks["DIR-LG-A0"]["qualification_evidence"]["slack_deliveries"]
                            if r.get("notification_key") == "terminal")
        terminal_row["projection_digest"] = "sha256:" + "0" * 64
        self.assertNotEqual(world.state("09"), "PASS")

    def test_companion_rows_and_producer_fields_are_required_in_every_state(self):
        """4110553559: a reconciliation event names a reservation. 4110553565: a live roster success has its result
        packet. 4110553569: a decision follows its prompt. 4110553571: the reservation digest exactly where the
        state is reserved, reason codes per state, the deployment id."""
        import copy
        from director_orchestrator import primary_scorecard_evidence as evidence

        def errors(readback):
            return {key: value for key, value in evidence.task_evidence_errors(readback)[1].items() if value}

        base = tf.readback_fixture()
        orphan = copy.deepcopy(base)
        orphan["reconciliation_events"] = [{"event_id": 1, "claim_key": "sha256:" + "9" * 64, "state": "AMBIGUOUS",
                                            "evidence_digest": "sha256:" + "9" * 64,
                                            "recorded_at": "2026-09-12T10:00:28+00:00"}]
        self.assertIn("effects", errors(orphan))
        # The inverse packet join: live roster successes only (an event-3 callback or an offline double persists none).
        live = {**copy.deepcopy(base), "execution_mode": "paid"}
        latest = evidence.task_evidence_errors(live)[0]
        self.assertEqual(evidence.missing_result_packets(live, latest), [live["assignments"][0]["assignment_id"]])
        self.assertEqual(evidence.missing_result_packets(
            {**live, "result_artifacts": [{"assignment_id": live["assignments"][0]["assignment_id"]}]}, latest), [])
        self.assertEqual(evidence.missing_result_packets(base, latest), [])  # offline_simulation
        called_back = {key: {**event, "event_sequence": 3} for key, event in latest.items()}
        self.assertEqual(evidence.missing_result_packets(live, called_back), [])
        # A decision recorded before Slack's ts for its prompt.
        delivered = base["slack_deliveries"][0]
        self.assertTrue(evidence.decision_follows_prompt({**delivered, "owner_decision_at": None}))
        early = {**delivered, "notification_key": "approval:sha256:" + "8" * 64 + ":" + base["projection_digest"],
                 "client_msg_id": "approval-message", "owner_decision": "approve", "owner_command_id": "command-1",
                 "owner_decision_at": "2026-09-12T10:00:21+00:00"}
        self.assertFalse(evidence.decision_follows_prompt(early))
        prompted = copy.deepcopy(base)
        prompted["slack_deliveries"].append(early)
        self.assertIn("deliveries", errors(prompted))
        self.assertTrue(evidence.decision_follows_prompt({**early, "owner_decision_at": "2026-09-12T10:00:45+00:00"}))
        # Assignment columns per state.
        assignment = base["assignments"][0]
        for label, change in (("reserved without its digest", {"reservation_digest": None}),
                              ("settled without a reason", {"reason_code": None}),
                              ("no deployment", {"deployment_id": None})):
            broken = copy.deepcopy(base)
            broken["assignments"][0].update(change)
            with self.subTest(label):
                self.assertNotEqual(errors(broken), {})
        cancelled = {**assignment, "status": "FAILED", "reason_code": "task_cancelled_before_dispatch",
                     "reserved_at": None, "reservation_digest": None, "result_digest": None}
        self.assertTrue(evidence.assignment_contract(cancelled))
        self.assertFalse(evidence.assignment_contract({**cancelled, "reservation_digest": "sha256:" + "a" * 64}))
        self.assertTrue(evidence.assignment_contract({**assignment, "status": "PENDING", "reserved_at": None,
                                                      "reservation_digest": None, "reason_code": "paid_setup_required"}))
        self.assertFalse(evidence.assignment_contract({**assignment, "status": "PENDING", "reserved_at": None,
                                                       "reason_code": None}))  # a digest on an unreserved row
        self.assertFalse(evidence.assignment_contract({**assignment, "status": "ACTIVE", "completed_at": None}))

