    def test_authority_and_source_bindings_are_checked_on_every_evidence_row(self):
        """4111725044/48/51: remote bindings carry their claim's owner; terminal rows and reconciliation events the
        claim's (or an authorized successor's) authority, all compared in SQL and served as booleans; status receipts
        carry their producer-derived id, their task's thread and the evaluator's owner."""
        import copy
        from director_orchestrator.primary_scorecard_evidence import task_evidence_errors

        def errors(readback, **source):
            sections = {**readback, **{"source_" + key: value for key, value in source.items()}}
            return {key: value for key, value in task_evidence_errors(sections)[1].items() if value}

        base = tf.readback_fixture()
        bound = dict(channel_id=tf.ENV["SLACK_DIRECTOR_CHANNEL_ID"], thread_ts=tf.THREAD, owner_user_id=tf.OWNER)
        self.assertEqual(errors(base, **bound), {})
        for key in ("binding_owner_matches", "terminal_authority_matches"):
            for value in (False, None):
                broken = copy.deepcopy(base)
                broken["effects"][0][key] = value
                with self.subTest(key=key, value=value):
                    self.assertIn("effects", errors(broken, **bound))
        effect = base["effects"][0]
        for value in (False, None):
            broken = copy.deepcopy(base)
            broken["reconciliation_events"] = [{"event_id": 1, "claim_key": effect["claim_key"], "state": "AMBIGUOUS",
                                                "evidence_digest": "sha256:" + "9" * 64,
                                                "recorded_at": effect["terminal_recorded_at"], "authority_matches": value}]
            with self.subTest(reconciliation=value):
                self.assertIn("effects", errors(broken, **bound))
        receipt = base["status_receipts"][0]
        for label, change, source in (
                ("another receipt id", {"receipt_id": "status-" + "0" * 24}, bound),
                ("another thread", {"thread_ts": "1789999999.000100"}, bound),
                ("another channel", {"channel_id": "COTHER"}, bound),
                ("another user", {"user_id": "UOTHER"}, bound),
                ("no text digest", {"text_digest": None}, bound),
                ("the evaluator's owner differs", {}, {**bound, "owner_user_id": "UOTHER"})):
            broken = copy.deepcopy(base)
            broken["status_receipts"][0] = {**receipt, **change}
            with self.subTest(label):
                self.assertIn("deliveries", errors(broken, **source))
        # The collector binds receipts to the task's own intake and the owner it is given (the evaluator's).
        task = {"intake": {"channel_id": tf.ENV["SLACK_DIRECTOR_CHANNEL_ID"], "thread_ts": tf.THREAD},
                "qualification_evidence": base}
        self.assertEqual(tf.collector_module._readback(tf.TASK_ID, task, tf.OWNER)[2], "collected")
        self.assertEqual(tf.collector_module._readback(tf.TASK_ID, task, "UOTHER")[2], "rejected")
        self.assertEqual(tf.collector_module._readback(tf.TASK_ID, task)[2], "rejected")  # no configured owner

    def test_scorecard_grades_only_from_the_pinned_evaluator_checkout(self):
        """Operating rule added by the author (reviews 4111508075 and 4111508073): the scorecard grades only from the
        owner-pinned evaluator revision, a clean checkout whose HEAD is evaluator_sha, which is on github/main and an
        ancestor of (or equal to) the candidate graded as data. Otherwise every check is UNKNOWN."""
        def git(results, calls):
            def run(arguments, timeout=15):
                calls.append(arguments[3:])
                value = results[(arguments[3], arguments[-1])] if (arguments[3], arguments[-1]) in results \
                    else results[arguments[3]]
                if isinstance(value, Exception):
                    raise value
                return value
            return run
        clean = {"merge-base": b""}
        tree = Path(sc.__file__).resolve().parents[2]
        launched = {"DIRECTOR_SCORECARD_TREE": str(tree), "DIRECTOR_SCORECARD_REPO": str(tree),
                    "DIRECTOR_SCORECARD_EVALUATOR_SHA": EVALUATOR}
        with patch.object(sc, "cli_release_descriptor", return_value=None):
            self.assertEqual(sc.untrusted_checkout(SHA), "evaluator revision not pinned")
        with patch.object(sc, "cli_release_descriptor", return_value=EVALUATED):
            with patch.dict(os.environ, {"DIRECTOR_SCORECARD_TREE": "", "DIRECTOR_SCORECARD_REPO": ""}):
                self.assertIn("owner-installed launcher", sc.untrusted_checkout(SHA))  # a direct run
            with patch.dict(os.environ, {**launched, "DIRECTOR_SCORECARD_TREE": str(tree.parent)}):
                self.assertIn("owner-installed launcher", sc.untrusted_checkout(SHA))  # another tree
            # Review 4112533825: a descriptor rotated after extraction (another evaluator_sha) refuses.
            with patch.dict(os.environ, {**launched, "DIRECTOR_SCORECARD_EVALUATOR_SHA": "1" * 40}):
                self.assertIn("no longer pins", sc.untrusted_checkout(SHA))
            with patch.dict(os.environ, launched):
                calls = []
                with patch.object(sc, "_run_bytes", side_effect=git(clean, calls)):
                    self.assertIsNone(sc.untrusted_checkout(SHA))
                # Both ancestry proofs ran: the evaluator on github/main, and the evaluator before the candidate.
                self.assertIn(("merge-base", "--is-ancestor", EVALUATOR, "github/main"), [tuple(c) for c in calls])
                self.assertIn(("merge-base", "--is-ancestor", EVALUATOR, SHA), [tuple(c) for c in calls])
                with patch.object(sc, "_run_bytes", side_effect=git(
                        {**clean, ("merge-base", "github/main"): ValueError("not an ancestor")}, [])):
                    self.assertIn("github/main", sc.untrusted_checkout(SHA))
                with patch.object(sc, "_run_bytes", side_effect=git(
                        {**clean, ("merge-base", SHA): ValueError("not an ancestor")}, [])):
                    self.assertIn("not an ancestor of the candidate", sc.untrusted_checkout(SHA))
        report = sc.refuse_untrusted(sc.score(SHA, [], now=NOW), "evaluator revision not pinned")
        self.assertEqual(sum(item["status"] == "PASS" for item in report["checks"]), 0)
        self.assertTrue(all(item["status"] == "UNKNOWN" and item["explanation"].startswith(sc.TRUSTED_CHECKOUT_REFUSAL)
                            and "evaluator revision not pinned" in item["explanation"] for item in report["checks"]))

