    def test_allowances_never_exceed_their_cap_under_float_error(self):
        """CI on a9ce209 (Windows): (t + 0.4) - t came out as 0.40000000002. Allowances round down to the
        microsecond, so a timeout never exceeds the cap or the time left."""
        with patch.object(sc.time, "monotonic", return_value=1789210000.1):
            end = 1789210000.1 + 0.4
            self.assertGreater(end - 1789210000.1, 0.4)  # the raw subtraction overshoots
            self.assertLessEqual(sc._left(end), 0.4)
            sc._DEADLINE[0] = end
            try:
                self.assertLessEqual(sc._remaining(5), 0.4)
            finally:
                sc._DEADLINE[0] = None

    def test_http_read_is_bounded_by_wall_clock_while_headers_trickle(self):
        """4109777101: httpx's timeouts bound only each read's inactivity, so headers trickled byte by byte could hold
        client.stream() open past the deadline; the whole request now runs under the absolute end."""
        def handle(request):
            time.sleep(3)  # the response (status line and headers) has not finished arriving
            return httpx.Response(200, content=b"{}")

        with httpx.Client(transport=httpx.MockTransport(handle)) as client:
            started = time.monotonic()
            with self.assertRaisesRegex(ValueError, "time bound"):
                sc.bounded_get(client, HEALTH, end=time.monotonic() + 0.3)
            self.assertLess(time.monotonic() - started, 1.5)
            status, _, body = sc.bounded_get(
                httpx.Client(transport=httpx.MockTransport(lambda request: httpx.Response(200, content=b"{}"))),
                HEALTH, end=time.monotonic() + 5)
            self.assertEqual((status, body), (200, b"{}"))

    def test_subprocess_cleanup_ends_the_tree_and_never_waits_on_an_inherited_pipe(self):
        """4109777106: a descendant that inherits stdout keeps the pipe open after its parent exits; the whole tree is
        ended and nothing (reader join, stream close) waits past the call's own clock."""
        spawn = ("import subprocess,sys; subprocess.Popen([sys.executable,'-c','import time; time.sleep(60)']); "
                 "print('ok', flush=True)")
        started = time.monotonic()
        self.assertEqual(sc._run_bytes([sys.executable, "-c", spawn], timeout=20).strip(), b"ok")
        self.assertLess(time.monotonic() - started, 15)
        started = time.monotonic()
        with self.assertRaises(subprocess.TimeoutExpired):
            sc._run_bytes([sys.executable, "-c", spawn + "; import time; time.sleep(60)"], timeout=1)
        self.assertLess(time.monotonic() - started, 10)

    def test_cleanup_spends_only_what_remains_of_the_command_deadline(self):
        """4111508057: cleanup never gets a fresh grace past the deadline; with nothing left the tree is killed at
        once and reaping is abandoned to a daemon thread."""
        graces = []
        real = sc.stop_contained_process

        def recording(process, guard, *, grace_seconds=5.0):
            graces.append(grace_seconds)
            return real(process, guard, grace_seconds=grace_seconds)

        with patch.object(sc, "stop_contained_process", side_effect=recording):
            started = time.monotonic()
            with self.assertRaises(subprocess.TimeoutExpired):
                sc._run_bytes([sys.executable, "-c", "import time; time.sleep(30)"], timeout=1)
            self.assertLess(time.monotonic() - started, 5)
        self.assertEqual(len(graces), 1)
        self.assertLess(graces[0], 0.5)  # what was left of the 1-second deadline, never a fresh 5 seconds

    def test_run_bytes_piped_print_ok_is_exactly_ok(self):
        """#388 Ubuntu run 36896064850 failed at the original print('ok')
        equality (test_subprocess_output_is_capped_on_both_pipes_while_running
        line 5281): AssertionError, payload redacted. That is the only proven
        Ubuntu failure. Overflow elapsed is a later assertion in the same
        method, not this one. Tree-kill, leftover _DEADLINE, and PIPE block
        buffering are inferences: a leftover deadline would raise
        TimeoutExpired or ValueError, not this equality. The original command
        is print('ok') without flush; a normal-exit child flushes stdio, so
        flush=True would hide the original command rather than bind it.
        Clearing _DEADLINE here is isolation hygiene, not a proven cause."""
        sc._DEADLINE[0] = None
        self.addCleanup(lambda: sc._DEADLINE.__setitem__(0, None))
        raw = sc._run_bytes([sys.executable, "-c", "print('ok')"])
        self.assertEqual(raw.strip(), b"ok", f"piped print('ok') stdout was {raw!r}")

    def test_subprocess_output_is_capped_on_both_pipes_while_running(self):
        sc._DEADLINE[0] = None
        self.addCleanup(lambda: sc._DEADLINE.__setitem__(0, None))
        raw = sc._run_bytes([sys.executable, "-c", "print('ok')"])
        self.assertEqual(raw.strip(), b"ok", f"normal stdout was {raw!r}")
        for pipe in ("stdout", "stderr"):
            # More than MAX_BYTES, then it would keep writing forever: killed on overflow, never parsed.
            script = ("import sys\nblock = b'x' * 65536\nwhile True:\n    sys.%s.buffer.write(block)\n" % pipe)
            started = time.monotonic()
            with self.subTest(pipe=pipe), self.assertRaises(ValueError):
                sc._run_bytes([sys.executable, "-c", script], timeout=60)
            self.assertLess(time.monotonic() - started, 30)
        with self.assertRaises(ValueError):
            sc._run_bytes([sys.executable, "-c", "import sys; sys.exit(3)"])

    def test_ten_offline_trials_10(self):
        self.assertEqual(self.world(evaluate_rules=True).state("10"), "PASS")
        called = self.world(evaluate_rules=True)
        called.add(task_entry("DIR-LG-7A01", 1000, offline=False,
                              text=called.tasks["DIR-LG-7A01"]["intake"]["text"]))
        report = called.report()
        self.assertEqual(row(report, "10")["status"], "FAIL")
        self.assertIn("DIR-LG-7A01", row(report, "10")["explanation"])
        world = self.world(evaluate_rules=True)
        report = world.report(trials=world.trials[:9])
        self.assertEqual(row(report, "10")["status"], "UNKNOWN")
        late = self.world(evaluate_rules=True)
        late.rows[0]["Created"] = "2026-09-12T13:40:00Z"  # after the last trial ran (~13:34)
        report = late.report()
        self.assertEqual(row(report, "10")["status"], "UNKNOWN")
        self.assertIn("runtime_sha", row(report, "10")["explanation"])
        wrong = self.world(evaluate_rules=True)
        wrong.tasks["DIR-LG-7A02"]["status"] = "FAILED"
        self.assertEqual(wrong.state("10"), "FAIL")
        # An edited terminal reply keeps its ts but not the text it was posted with.
        edited = self.world(evaluate_rules=True)
        final = next(m for m in edited.threads[ts(2000)] if m.get("ts") == ts(2030))
        final["edited"] = {"user": BOT, "ts": ts(2090)}
        self.assertNotEqual(edited.state("10"), "PASS")
        missing = self.world(evaluate_rules=True)
        missing.failing.add(missing.trials[3])
        self.assertEqual(missing.state("10"), "UNKNOWN")
        # Ten passing threads are not enough: they must be consecutive owner posts.
        skipped = self.world(evaluate_rules=True)
        skipped.history_extra.append({"ts": ts(1500), "user": OWNER, "text": "DIRECTOR another trial"})
        report = skipped.report()
        self.assertEqual(row(report, "10")["status"], "UNKNOWN")
        self.assertIn("consecutive", row(report, "10")["explanation"])
        shared_file = self.world(evaluate_rules=True)
        shared_file.history_extra.append({"ts": ts(1500), "user": OWNER, "subtype": "file_share", "text": "DIRECTOR x"})
        self.assertEqual(shared_file.state("10"), "UNKNOWN")
        # A deleted post leaves a tombstone that may be a skipped trial.
        deleted = self.world(evaluate_rules=True)
        deleted.history_extra.append({"ts": ts(1500), "user": "USLACKBOT", "subtype": "tombstone", "hidden": True,
                                      "text": "This message was deleted."})
        self.assertEqual(deleted.state("10"), "UNKNOWN")
        # Every trial must itself be a visible top-level post in the window.
        not_a_post = self.world(evaluate_rules=True)
        not_a_post.history_hidden.add(not_a_post.trials[4])
        self.assertEqual(not_a_post.state("10"), "UNKNOWN")
        chatter_from_bot = self.world(evaluate_rules=True)
        chatter_from_bot.history_extra.append({"ts": ts(1500), "user": BOT, "bot_id": "BBOT123", "text": "status"})
        self.assertEqual(chatter_from_bot.state("10"), "PASS")
        no_history = self.world(evaluate_rules=True)
        no_history.failing.add("history")
        self.assertEqual(no_history.state("10"), "UNKNOWN")

    def test_real_products_11(self):
        self.assertEqual(self.world(evaluate_rules=True).state("11"), "PASS")
        for lane, product in (("cursor", None), ("grok", None), ("openai", "xai-grok-cli")):
            case = self.world(evaluate_rules=True)
            readback = case.tasks[PAID_TASK]["qualification_evidence"]
            case.tasks[PAID_TASK]["qualification_evidence"] = tf.seal(
                json.loads(json.dumps(readback).replace('"claude"', f'"{lane}"')))
            if lane in case.captures["lanes"]:
                set_product(case.captures, lane, product)
            with self.subTest(lane=lane):
                self.assertEqual(case.state("11"), "FAIL")
        # Owner ruling 2026-09-26 ("Bind to pinned release"): grok and Claude CLI captures are held to Codex's
        # standard. Unattested: UNKNOWN on their own CLI transport, a substitution on another product's.
        def cli_lane(lane, product, transport):
            case = self.world(evaluate_rules=True)
            case.tasks[PAID_TASK]["qualification_evidence"] = tf.seal(json.loads(
                json.dumps(case.tasks[PAID_TASK]["qualification_evidence"]).replace('"claude"', f'"{lane}"')
                .replace('"native-cli"', f'"{transport}"')))
            set_product(case.captures, lane, product)
            return case.state("11")
        for lane, product in (("grok", "xai-grok-cli"), ("claude", "anthropic-claude")):
            with self.subTest(lane=lane):
                for transport in ("native-cli", "authenticated-windows-host-bridge", "some-proxy"):
                    self.assertEqual(cli_lane(lane, product + "-unattested", transport), "UNKNOWN")
                self.assertEqual(cli_lane(lane, product + "-unattested", "responses-api"), "FAIL")
                # A release-attested CLI product passes on its own transport only.
                self.assertEqual(cli_lane(lane, product, "native-cli"), "PASS")
                self.assertEqual(cli_lane(lane, product, "responses-api"), "FAIL")
                self.assertEqual(cli_lane(lane, product, "some-proxy"), "UNKNOWN")
        self.assertEqual(cli_lane("grok", "xai-grok-responses", "native-cli"), "FAIL")  # no longer a product
        def openai_lane(product, transport):
            case = self.world(evaluate_rules=True)
            readback = json.dumps(case.tasks[PAID_TASK]["qualification_evidence"])
            case.tasks[PAID_TASK]["qualification_evidence"] = tf.seal(json.loads(
                readback.replace('"claude"', '"openai"').replace('"native-cli"', f'"{transport}"')))
            set_product(case.captures, "openai", product)
            return case.state("11")
        # The OpenAI capture must be the product the attempts' transport actually used. Review 4102705154: a Codex
        # stream names no product or model, so a Codex lane is unattested (UNKNOWN), never credited as Codex.
        for transport in ("native-cli", "authenticated-windows-host-bridge", "some-proxy"):
            with self.subTest(transport=transport):
                self.assertEqual(openai_lane("openai-codex-unattested", transport), "UNKNOWN")
        # Codex is creditable only as a release-attested CLI product (cli_release_product), on a CLI transport.
        self.assertEqual(openai_lane("openai-codex", "native-cli"), "PASS")
        self.assertEqual(openai_lane("openai-codex", "responses-api"), "FAIL")
        self.assertEqual(openai_lane("openai-responses", "native-cli"), "FAIL")
        self.assertEqual(openai_lane("openai-codex-unattested", "responses-api"), "FAIL")
        # 4109777108: a Responses envelope from a route not bound to the official OpenAI endpoint is unattested:
        # UNKNOWN on the Responses transport, a substitution on another product's transport.
        self.assertEqual(openai_lane("openai-responses-unattested", "responses-api"), "UNKNOWN")
        self.assertEqual(openai_lane("openai-responses-unattested", "native-cli"), "FAIL")
        self.assertEqual(openai_lane("openai-responses", "responses-api"), "PASS")
        # Captures must be the ones that gated the paid attempts, under the running bindings.
        for required in (["claude", "grok", "openai", "cursor"], ["claude", "grok"], None):
            case = self.world(evaluate_rules=True)
            case.captures["required_providers"] = required
            with self.subTest(required=required):
                self.assertEqual(case.state("12"), "FAIL")
        # Freshness is measured from the collection's end: a capture observed during collection is current,
        # and one expiring within FRESH_FOR of the end is not.
        during = self.world(evaluate_rules=True)
        during.until = datetime(2026, 9, 12, 20, 5, tzinfo=timezone.utc)
        for lane in during.captures["lanes"].values():
            lane["surfaces"]["app"]["observed_at"] = "2026-09-12T20:03:00+00:00"
            lane["surfaces"]["app"]["recorded_at"] = "2026-09-12T20:03:01+00:00"  # persisted after it was observed
        during.captures["observed_at"] = "2026-09-12T20:04:00+00:00"
        during.consistency["captured_at"] = "2026-09-12T20:04:00+00:00"
        self.assertEqual(during.state("12"), "PASS")
        expiring = self.world(evaluate_rules=True)
        expiring.until = datetime(2026, 9, 12, 20, 5, tzinfo=timezone.utc)
        expiring.captures["observed_at"] = expiring.consistency["captured_at"] = "2026-09-12T20:04:00+00:00"
        expiring.captures["lanes"]["claude"]["surfaces"]["app"]["expires_at"] = "2026-09-12T20:07:00+00:00"
        self.assertEqual(expiring.state("12"), "FAIL")
        future_capture = self.world(evaluate_rules=True)
        for lane in future_capture.captures["lanes"].values():
            lane["surfaces"]["app"]["observed_at"] = "2026-09-12T21:00:00+00:00"
        self.assertNotEqual(future_capture.state("12"), "PASS")
        # Both surfaces gate the attempt: an app capture persisted after it does not attest the lane.
        late_app = self.world(evaluate_rules=True)
        first_attempt = late_app.tasks[PAID_TASK]["qualification_evidence"]["provider_attempts"][0]["recorded_at"]
        late_app.captures["lanes"]["claude"]["surfaces"]["app"]["recorded_at"] = (
            datetime.fromisoformat(first_attempt) + timedelta(seconds=4)).isoformat()
        self.assertEqual(late_app.state("11"), "UNKNOWN")
        minted_later = self.world(evaluate_rules=True)
        minted_later.captures["lanes"]["claude"]["surfaces"]["runtime_adapter"]["observed_at"] = (
            datetime.fromisoformat(first_attempt) + timedelta(seconds=4)).isoformat()
        self.assertEqual(minted_later.state("11"), "UNKNOWN")
        expired_during = self.world(evaluate_rules=True)
        expired_during.captures["lanes"]["claude"]["surfaces"]["runtime_adapter"]["expires_at"] = (
            datetime.fromisoformat(first_attempt) + timedelta(seconds=14)).isoformat()
        self.assertEqual(expired_during.state("11"), "UNKNOWN")
        # A backdated observed_at does not help: the row's persisted insertion time must precede the attempts too.
        published_later = self.world(evaluate_rules=True)
        published_later.captures["lanes"]["claude"]["surfaces"]["runtime_adapter"]["recorded_at"] = (
            datetime.fromisoformat(first_attempt) + timedelta(seconds=4)).isoformat()
        self.assertEqual(published_later.state("11"), "UNKNOWN")
        unrecorded = self.world(evaluate_rules=True)
        unrecorded.captures["lanes"]["claude"]["surfaces"]["runtime_adapter"]["recorded_at"] = None
        self.assertEqual(unrecorded.state("11"), "UNKNOWN")
        undated = self.world(evaluate_rules=True)
        del undated.captures["lanes"]["claude"]["surfaces"]["runtime_adapter"]["observed_at"]
        self.assertEqual(undated.state("11"), "UNKNOWN")
        recreated = self.world(evaluate_rules=True)
        recreated.rows[0]["Created"] = "2026-09-12T16:30:00Z"  # after the paid attempt (~16:20)
        self.assertEqual(recreated.state("11"), "UNKNOWN")
        rebound = self.world(evaluate_rules=True)
        rebound.captures["provider_bindings_sha256"] = "0" * 64
        self.assertEqual(rebound.state("11"), "UNKNOWN")
        regenerated = self.world(evaluate_rules=True)
        regenerated.captures["generation_manifest_sha256"] = "0" * 64
        self.assertEqual(regenerated.state("11"), "UNKNOWN")
        # A capture that no longer verifies reports no product: stale evidence, not a substitution.
        unverified = self.world(evaluate_rules=True)
        unverified.captures["lanes"]["claude"]["surfaces"]["runtime_adapter"]["capture_verified"] = False
        set_product(unverified.captures, "claude", None)
        self.assertEqual(unverified.state("11"), "UNKNOWN")
        # A verified, bound capture that names no product is still a substitution.
        productless = self.world(evaluate_rules=True)
        set_product(productless.captures, "claude", None)
        self.assertEqual(productless.state("11"), "FAIL")
        report = self.world(evaluate_rules=True).report(paid_thread=None, paid_rubric_path=None)
        self.assertEqual(row(report, "11")["status"], "UNKNOWN")
        unavailable = self.world(evaluate_rules=True)
        unavailable.captures = None
        self.assertEqual(unavailable.state("11"), "UNKNOWN")

